await test('Fahrzeugimport: Vorschau (neu/geändert/unverändert), leere Spalten löschen keine Stammdaten, Anführungszeichen', async () => {
  const H = { 'content-type': 'text/csv' };
  eq((await owner.post('/api/vehicles', { plate: 'IM-P 1', vin: 'WDB96340310888001', site: 'Dortmund', manufacturer: 'Mercedes-Benz', model: 'Actros 1845' })).status, 201);
  const csv = 'Kennzeichen;FIN;Fahrzeugart;Quelle\nIM-P 1;WDB96340310888001;Lkw;"Beleg A; mit Semikolon"\nIM-P 2;WDB96340310888002;Anhänger;Beleg B\nIM-X;UNGUELTIG;Lkw;x';
  const pre = await owner.req('POST', '/api/vehicles/import?dry_run=1', csv, H);
  eq(pre.status, 200); eq(pre.data.dry_run, true);
  eq(pre.data.counts.neu, 1); eq(pre.data.counts.unveraendert, 1); eq(pre.data.skipped.length, 1);
  eq((await owner.get('/api/vehicles/VIN:WDB96340310888002')).status, 404, 'Vorschau legt nichts an');
  const go = await owner.req('POST', '/api/vehicles/import', csv, H);
  eq(go.data.imported, 2);
  const v1 = (await owner.get('/api/vehicles/VIN:WDB96340310888001')).data.vehicle;
  eq(v1.manufacturer, 'Mercedes-Benz', 'Hersteller bleibt'); eq(v1.model, 'Actros 1845', 'Modell bleibt'); eq(v1.site, 'Dortmund', 'Standort bleibt');
  eq(v1.source, 'CSV-Import: Beleg A; mit Semikolon', 'Anführungszeichen korrekt gelesen');
  const ch = await owner.req('POST', '/api/vehicles/import?dry_run=1', 'Kennzeichen;FIN;Standort\nIM-P 1 NEU;WDB96340310888001;München', H);
  const row = ch.data.preview[0];
  eq(row.action, 'geändert'); ok(row.changes.some((c) => c.field === 'plate' && c.to === 'IM-P 1 NEU') && row.changes.some((c) => c.field === 'site' && c.from === 'Dortmund'), 'Änderungen benannt');
  eq(pre.data.counts.plate_conflict, 0, 'ohne gleiches Kennzeichen kein Hinweis'); ok(!pre.data.preview.some((x) => x.plate_conflict));
  // Kennzeichen nach dem Import an zwei Fahrzeugen (FIN-Tippfehler, andere Schreibweise; auch innerhalb der Datei) → Hinweis, Import bleibt möglich
  const dup = await owner.req('POST', '/api/vehicles/import?dry_run=1', 'Kennzeichen;FIN\nim-p2;WDB96340310888012\nIM-Q 7;WDB96340310888013\nIM Q7;WDB96340310888014\nIM-P 1;WDB96340310888001', H);
  const pc = new Map(dup.data.preview.map((x) => [x.vin, x.plate_conflict]));
  eq(JSON.stringify(pc.get('WDB96340310888012')), JSON.stringify(['WDB96340310888002']), 'gegen Bestand');
  eq(JSON.stringify(pc.get('WDB96340310888013')), JSON.stringify(['WDB96340310888014']), 'innerhalb der Datei');
  eq(pc.get('WDB96340310888001'), undefined, 'eigenes Fahrzeug zählt nicht'); eq(dup.data.counts.plate_conflict, 3);
  // Umbenennung in der Datei hebt den Konflikt auf (maßgeblich ist das Kennzeichen nach dem Import)
  eq((await owner.req('POST', '/api/vehicles/import?dry_run=1', 'Kennzeichen;FIN\nIM-P 2;WDB96340310888012\nIM-P 2 ALT;WDB96340310888002', H)).data.counts.plate_conflict, 0, 'Datei vor Bestand');
  for (const v of ['WDB96340310888001', 'WDB96340310888002']) await owner.post(`/api/vehicles/VIN:${v}/active`, { active: false, reason: 'Testdaten Import' });
});

await test('Bußgelder: CSV (Fahrer nur auf Wunsch) und Fristenkalender ohne Namen; ICS-Text korrekt maskiert', async () => {
  const dec = (r) => new TextDecoder('utf-8', { ignoreBOM: true }).decode(r.data);
  await users.fleet.post('/api/fines', { kind: 'bussgeldbescheid', authority: 'Bußgeldstelle Süd; Abt. 3', reference: 'AZ-ICS-1', offense_type: 'parken', offense_at: new Date().toISOString(), plate_in_letter: 'SZ YC 5513', amount_eur: 35.5, response_due: '2040-03-15' });
  const csv = await users.fleet.get('/api/fines?format=csv');
  eq(csv.status, 200); const t = dec(csv);
  ok(t.startsWith('\ufeffVorgang;Art;Behörde') && !t.includes(';Fahrer') && t.includes('35,5'), 'ohne Fahrer, Komma-Betrag');
  // Tatzeit wie im Schreiben (Berliner Ortszeit), nicht als UTC-Zeitstempel
  const fz = (await users.fleet.get('/api/fines')).data.fines.find((f) => f.reference === 'AZ-ICS-1');
  const { berlinDateTime } = await import('../src/util.js');
  const { maintenanceHistoryCsv } = await import('../src/maintenance.js');
  ok(maintenanceHistoryCsv({ rows: [{ plate: 'X', vehicle_id: 'VIN:X', kind: 'HU', done_date: '2026-10-12', created_at: '2026-10-12T22:30:00.000Z' }] }).includes(';2026-10-13;'), 'Prüfhistorie: „Erfasst am“ als Berliner Tag');
  ok(t.includes(';' + berlinDateTime(fz.offense_at) + ';') && !t.includes(fz.offense_at), 'Tatzeit Berlin: ' + berlinDateTime(fz.offense_at));
  eq(berlinDateTime('2026-07-01T06:30:00.000Z'), '01.07.2026 08:30', 'Sommerzeit'); eq(berlinDateTime('2026-12-01T06:30:00.000Z'), '01.12.2026 07:30', 'Winterzeit');
  ok(dec(await users.fleet.get('/api/fines?format=csv&with_driver=1')).split('\r\n')[0].endsWith(';Fahrer'), 'mit Fahrer auf Wunsch');
  eq((await users.driver.get('/api/fines?format=csv')).status, 403);
  const ics = dec(await users.fleet.get('/api/fines?format=ics'));
  ok(ics.includes('DTSTART;VALUE=DATE:20400315') && ics.includes('Bußgeldstelle Süd\\; Abt. 3'), 'Frist mit maskiertem Semikolon');
  try {
    eq((await owner.put('/api/settings', { fine_warn_days: '' })).status, 200);
    ok(!dec(await users.fleet.get('/api/fines?format=ics')).includes('VALARM'), 'leer = keine Erinnerung');
    eq((await owner.put('/api/settings', { fine_warn_days: '0' })).status, 200);
    ok(dec(await users.fleet.get('/api/fines?format=ics')).includes('TRIGGER:-P0D'), '0 = Erinnerung am Fristtag (wie Agent; vorher keine)');
    eq((await owner.put('/api/settings', { fine_warn_days: '14' })).status, 200);
    ok(dec(await users.fleet.get('/api/fines?format=ics')).includes('TRIGGER:-P14D'));
  } finally { await owner.put('/api/settings', { fine_warn_days: '' }); }
  const { icsEscape } = await import('../src/util.js');
  eq(icsEscape('a;b,c\\d\nx'), 'a\\;b\\,c\\\\d\\nx');
  eq(icsEscape('a\rb\r\nc\u0000d\u001be\tf'), 'a\\nb\\ncd' + 'e\tf', 'einzelnes CR → \\n, Steuerzeichen entfernt, Tab bleibt');
});

await test('Bußgelder: Tatzeit ohne Zeitzone = Berliner Ortszeit wie im Schreiben (unabhängig vom Gerät), ungültige Uhrzeit abgewiesen', async () => {
  const { berlinLocalToIso } = await import('../src/util.js');
  eq(berlinLocalToIso('2026-07-01T08:30'), '2026-07-01T06:30:00.000Z', 'Sommerzeit');
  eq(berlinLocalToIso('2026-12-01T08:30'), '2026-12-01T07:30:00.000Z', 'Winterzeit');
  eq(berlinLocalToIso('2026-03-29T03:30'), '2026-03-29T01:30:00.000Z', 'nach Umstellung März');
  eq(berlinLocalToIso('2026-10-25T01:59'), '2026-10-24T23:59:00.000Z', 'vor Umstellung Oktober');
  eq(berlinLocalToIso('2026-07-01T08:30:00Z'), '2026-07-01T08:30:00Z', 'mit Zeitzone unverändert');
  eq(berlinLocalToIso('2026-02-30T08:00'), null); eq(berlinLocalToIso('2026-07-01T24:00'), null);
  const base = { kind: 'verwarnung', authority: 'Ordnungsamt Zeitzone', offense_type: 'parken', plate_in_letter: 'XX-TZ 1', response_due: '2040-05-01' };
  const r = await users.fleet.post('/api/fines', { ...base, reference: 'AZ-TZ-1', offense_at: '2026-07-01T08:30' });
  eq(r.status, 201);
  const f = (await users.fleet.get('/api/fines')).data.fines.find((x) => x.reference === 'AZ-TZ-1');
  eq(f.offense_at, '2026-07-01T06:30:00.000Z', 'gespeichert als UTC');
  const r2 = await users.fleet.post('/api/fines', { ...base, reference: 'AZ-TZ-2', offense_at: '2026-07-01T08:30:00+02:00' });
  eq(r2.status, 201);
  eq((await users.fleet.get('/api/fines')).data.fines.find((x) => x.reference === 'AZ-TZ-2').offense_at, '2026-07-01T06:30:00.000Z', 'Zeitzone vereinheitlicht');
  for (const bad of ['2026-02-30T08:00', '2026-07-01T25:00', 'gestern']) eq((await users.fleet.post('/api/fines', { ...base, reference: 'AZ-TZ-X', offense_at: bad })).status, 400, bad);
});

await test('Bußgelder: Filter Fahrzeug-Standort (Schreibweise egal, ohne Fahrzeug = „ohne“, Summe = alle), CSV und Kalender gefiltert', async () => {
  const dec = (r) => new TextDecoder('utf-8', { ignoreBOM: true }).decode(r.data);
  eq((await users.fleet.post('/api/fines', { kind: 'verwarnung', authority: 'Ordnungsamt Standorttest', reference: 'AZ-SITE-UNBEKANNT', offense_type: 'parken', offense_at: new Date().toISOString(), plate_in_letter: 'XX-ZZ 9999', response_due: '2040-04-01' })).status, 201);
  const all = (await users.fleet.get('/api/fines')).data;
  eq(all.site, null);
  ok(all.site_options.includes('ohne'), '„ohne“ für Schreiben ohne erkanntes Fahrzeug');
  const known = all.fines.find((f) => f.reference === 'AZ-ICS-1'); ok(known && known.vehicle_site, 'Schreiben mit Fahrzeug-Standort');
  const ids = (l) => l.map((f) => f.id).sort();
  const union = [];
  for (const o of all.site_options) union.push(...(await users.fleet.get(`/api/fines?site=${encodeURIComponent(o)}`)).data.fines.map((f) => f.id));
  eq(JSON.stringify(union.sort()), JSON.stringify(ids(all.fines)), 'Summe über alle Standorte = alle Schreiben');
  const k = (await users.fleet.get(`/api/fines?site=${encodeURIComponent(known.vehicle_site.toUpperCase())}`)).data;
  ok(k.fines.some((f) => f.id === known.id) && !k.fines.some((f) => f.reference === 'AZ-SITE-UNBEKANNT'), 'Schreibweise egal, nur dieser Standort');
  ok((await users.fleet.get('/api/fines?site=ohne')).data.fines.some((f) => f.reference === 'AZ-SITE-UNBEKANNT'), 'ohne Fahrzeug unter „ohne“');
  eq((await users.fleet.get('/api/fines?site=Nirgendwo')).data.fines.length, 0, 'unbekannter Standort leer');
  const open = (await users.fleet.get('/api/fines?status=open&site=ohne')).data.fines;
  ok(open.length >= 1 && open.every((f) => !f.vehicle_site), 'kombinierbar mit „offen“');
  const csv = dec(await users.fleet.get('/api/fines?format=csv&site=ohne'));
  ok(csv.includes('AZ-SITE-UNBEKANNT') && !csv.includes('AZ-ICS-1'), 'CSV gefiltert');
  const ics = dec(await users.fleet.get(`/api/fines?format=ics&site=${encodeURIComponent(known.vehicle_site)}`));
  ok(ics.includes('20400315') && !ics.includes('20400401') && ics.includes('Behördenfristen – '), 'Kalender gefiltert und benannt');
  const viewer = await invite(owner, { username: 'test.lesen.finesite', display_name: 'Test Lesezugriff Standort', role: 'viewer', environment: 'test' });
  const vw = (await viewer.get('/api/fines?site=ohne')).data;
  ok(vw.fines.length >= 1 && vw.fines.every((f) => !('driver_id' in f)), 'Lesezugriff: Filter, weiterhin ohne Fahrer');
  const dr = (await users.driver.get('/api/fines?site=ohne')).data;
  eq(JSON.stringify(dr.site_options), '[]', 'Fahrer: keine Standortauswahl'); eq(dr.site, null);
});

await test('Kommentar gezielt benachrichtigen (nur Werkstatt / nur Meldende), Standard alle Beteiligten', async () => {
  const c = await users.driver.post('/api/cases', { vehicle_id: V1, description: 'Kommentartest Spiegel', priority: 'niedrig', driveability: 'fahrbereit', request_key: rk(), workshop_site: 'DORTMUND' });
  await users.fleet.post(`/api/cases/${c.data.id}/commands`, { action: 'receive', command_id: rk(), expected_version: 1 });
  await users.fleet.post(`/api/cases/${c.data.id}/commands`, { action: 'approve_repair', command_id: rk(), expected_version: 2, note: 'Spiegel tauschen', payload: { workshop_site: 'DORTMUND' } });
  const who = async () => new Set((await env.DB.prepare(`SELECT user_id FROM notifications WHERE case_id=? AND kind='comment'`).bind(c.data.id).all()).results.map((r) => r.user_id));
  eq((await users.fleet.post(`/api/cases/${c.data.id}/commands`, { action: 'comment', command_id: rk(), expected_version: 3, note: 'Nur an Werkstatt', payload: { notify: ['workshop'] } })).status, 200);
  let w = await who();
  ok(w.has(users.ws.id) && !w.has(users.driver.id), 'nur Werkstatt');
  const v = (await users.fleet.get(`/api/cases/${c.data.id}`)).data.case.version;
  await users.ws.post(`/api/cases/${c.data.id}/commands`, { action: 'comment', command_id: rk(), expected_version: v, note: 'Rückfrage an alle' });
  w = await who();
  ok(w.has(users.driver.id) && w.has(users.fleet.id), 'Standard: alle Beteiligten');
});

await test('Kosten je km: gefahrene km aus erster/letzter Ablesung im Zeitraum, ohne Rückgang; sonst kein Wert', async () => {
  // Zeitraum ab 2026-01 (alle Testablesungen): ohne „Von“ fielen sie ab Ende 2027 aus dem 13-Monats-Fenster (22.10.2026)
  const r = await users.fleet.get(`/api/reports/costs?from=2026-01&to=${COST_TO}`);
  eq(r.status, 200); ok(Array.isArray(r.data.vehicles));
  const v1 = r.data.vehicles.find((v) => v.vehicle_id === V1);
  const rows = (await env.DB.prepare('SELECT km FROM odometer_readings WHERE vehicle_id=? ORDER BY measured_at').bind(V1).all()).results;
  const exp = rows.length >= 2 && rows[rows.length - 1].km >= rows[0].km ? rows[rows.length - 1].km - rows[0].km : null;
  eq(v1.km, exp, 'km = letzte − erste Ablesung');
  if (exp) eq(v1.cost_per_km, Math.round((v1.actual_net / exp) * 1000) / 1000);
  const v2 = r.data.vehicles.find((v) => v.vehicle_id === V2);
  ok(!v2 || v2.km === null, 'Rückgang (Tachotausch) → kein km-Wert');
});

await test('Kosten je km wie „Fahrleistung je Monat“: exakte Berliner Monatsgrenzen, Vorwert aus dem Vormonat, km je Monat (API/CSV), Rückgang, Oberfläche', async () => {
  const vin = 'WDB96340310777703'; const VID = 'VIN:' + vin; const db = env.DB.db;
  eq((await users.fleet.post('/api/vehicles', { vin, plate: 'TZ-KM 1', site: 'Km-Regel-Test' })).status, 201);
  const add = (id, km, at) => db.prepare('INSERT INTO odometer_readings(id,vehicle_id,km,measured_at,source,recorded_by,created_at) VALUES (?,?,?,?,?,?,?)').run(id, VID, km, at, 'manuell', null, at);
  const src = db.prepare(`SELECT * FROM cases WHERE environment='test' LIMIT 1`).get(); const cols = Object.keys(src);
  const dec = (x) => new TextDecoder('utf-8', { ignoreBOM: true }).decode(x.data);
  const q = (x = '') => `/api/reports/costs?from=2026-03&to=2026-05&vehicle_id=${encodeURIComponent(VID)}${x}`;
  const get = async () => (await users.fleet.get(q())).data;
  try {
    add('tzkm-1', 1000, '2026-01-15T10:00:00.000Z'); // älter als der Vormonat → kein Vorwert
    add('tzkm-2', 2000, '2026-03-10T10:00:00.000Z');
    add('tzkm-3', 2500, '2026-03-31T22:30:00.000Z'); // Berlin: 01.04. 00:30 → April
    add('tzkm-4', 3000, '2026-04-20T10:00:00.000Z');
    add('tzkm-5', 9999, '2026-05-31T23:00:00.000Z'); // Berlin: 01.06. → außerhalb des Zeitraums
    db.prepare(`INSERT INTO cases(${cols.join(',')}) VALUES (${cols.map(() => '?').join(',')})`).run(...cols.map((c) => (c === 'id' ? 'tzkm-case' : c === 'case_no' ? 'TZKM-1' : c === 'request_key' ? 'tzkm-case' : c === 'vehicle_id' ? VID : c === 'duplicate_of' ? null : c === 'created_at' ? '2026-04-15T10:00:00.000Z' : src[c])));
    let r = await get(); let v = r.vehicles.find((x) => x.vehicle_id === VID);
    eq(v.km, 1000, 'ab erster Ablesung im Zeitraum (Ablesung im Januar zählt nicht), Juni-Ablesung (Berlin) nicht im Zeitraum');
    eq(v.km_basis, 'first_in_period'); eq(v.km_status, 'ok'); eq(v.km_from_at, '2026-03-10T10:00:00.000Z'); eq(v.km_to_at, '2026-04-20T10:00:00.000Z');
    eq(r.rows.length, 1); eq(r.rows[0].month, '2026-04'); eq(r.rows[0].km, 1000, 'April: letzte im April (3000) − letzte im März (2000; 31.03. 22:30 UTC ist schon April)');
    add('tzkm-0', 1800, '2026-02-20T10:00:00.000Z'); // Vorwert im Vormonat von „Von“
    r = await get(); v = r.vehicles.find((x) => x.vehicle_id === VID);
    eq(v.km, 1200, 'letzte im Zeitraum − letzte davor (Februar)'); eq(v.km_basis, 'previous'); eq(v.km_from_at, '2026-02-20T10:00:00.000Z');
    const pm = await periodMileageOf(VID);
    eq(pm.months.get('2026-03'), 200, 'März: 2000 − 1800'); eq(pm.months.get('2026-04'), 1000);
    // Summe der Monate = Zeitraum (wie Fahrzeugakte)
    eq([...pm.months.values()].reduce((s, x) => s + x, 0), v.km);
    let csv = dec(await users.fleet.get(q('&format=csv'))).split('\r\n');
    ok(csv[0].endsWith(';Gefahrene km (Monat);Fahrzeugstatus'), 'CSV-Spalte'); ok(csv[1].startsWith('TZ-KM 1;') && csv[1].endsWith(';1000;aktiv'), 'CSV April 1000 km');
    add('tzkm-6', 2900, '2026-04-25T10:00:00.000Z'); // Rückgang im April
    r = await get(); v = r.vehicles.find((x) => x.vehicle_id === VID);
    eq(v.km, null, 'Rückgang → kein Wert'); eq(v.km_status, 'decrease'); eq(v.cost_per_km, null); eq(r.rows[0].km, null, 'April ohne Wert');
    csv = dec(await users.fleet.get(q('&format=csv'))).split('\r\n'); ok(csv[1].endsWith('ja;;aktiv') || csv[1].endsWith('nein;;aktiv'), 'CSV leer statt 0');
    const pm2 = await periodMileageOf(VID); eq(pm2.months.get('2026-03'), 200, 'März bleibt');
    // Rückgang gegenüber dem Vorwert vor dem Zeitraum
    db.prepare(`DELETE FROM odometer_readings WHERE id='tzkm-6'`).run(); db.prepare(`UPDATE odometer_readings SET km=2100 WHERE id='tzkm-0'`).run();
    db.prepare(`UPDATE odometer_readings SET km=2050 WHERE id='tzkm-2'`).run();
    v = (await get()).vehicles.find((x) => x.vehicle_id === VID); eq(v.km, null, 'erste Ablesung im Zeitraum (2050) unter dem Vorwert (2100) → kein Wert'); eq(v.km_status, 'decrease');
    eq((await periodMileageOf(VID)).months.get('2026-03'), null, 'März ohne Wert');
  } finally {
    db.prepare(`DELETE FROM odometer_readings WHERE vehicle_id=?`).run(VID); db.prepare(`DELETE FROM cases WHERE id='tzkm-case'`).run();
  }
  // nur eine Ablesung, kein Vorwert → kein Wert
  add('tzkm-7', 5000, '2026-04-02T10:00:00.000Z');
  try { const v = (await get()).vehicles.find((x) => x.vehicle_id === VID); eq(v.km, null); eq(v.km_status, 'insufficient'); } finally { db.prepare(`DELETE FROM odometer_readings WHERE vehicle_id=?`).run(VID); }
  const app = await (await import('node:fs/promises')).readFile(new URL('../public/app.js', import.meta.url), 'utf8');
  ok(app.includes("data-ckm=\"span\"") && app.includes("t('ckm_first')") && app.includes("m.km !== null && m.km !== undefined ? ' · ' + fmtKm(m.km)"), 'Oberfläche: km-Stände, Basis und km je Monat');
  async function periodMileageOf(id) { const { periodMileage } = await import('../src/reports.js'); return (await periodMileage(env, '2026-03', '2026-05', id)).get(id); }
});

await test('Nur unbewertete Positionen: „Belegt“ zeigt „–“ statt 0 €, kein Wert je km (valued_items in Vorgang, Fahrzeug, Bericht, Standort, Summe)', async () => {
  const { computeCosts } = await import('../src/cases.js');
  let k = computeCosts(null, [{ hours: 2 }], [{ quantity: 1, unit_price_net: null, valuation: 'unvalued' }], []);
  eq(k.valued_items, 0); eq(k.unvalued_items, 2); eq(k.actual_net, 0);
  k = computeCosts(80, [{ hours: 1 }], [{ quantity: 1, unit_price_net: 0, valuation: 'actual' }, { quantity: 1, unit_price_net: 5, valuation: 'estimate' }], [{ amount_net: 10, valuation: 'actual' }]);
  eq(k.valued_items, 3, 'Arbeitszeit + belegtes Teil (auch 0 €) + Fremdleistung; Schätzung zählt nicht'); eq(k.actual_net, 90);
  eq(computeCosts(80, [], [{ quantity: 1, unit_price_net: 3, valuation: 'actual' }], [{ amount_net: 50, valuation: 'actual', covers_work_and_parts: 1 }]).valued_items, 1, 'ersetzte eigene Teile zählen nicht');
  const vin = 'WDB96340310777702'; const VID = 'VIN:' + vin; const db = env.DB.db;
  eq((await users.fleet.post('/api/vehicles', { vin, plate: 'TZ-UV 1', site: 'Unbewertet-Test' })).status, 201);
  const now = new Date(); const iso = (d) => new Date(now.getTime() - d * 86400000).toISOString();
  const src = db.prepare(`SELECT * FROM cases WHERE environment='test' LIMIT 1`).get(); const cols = Object.keys(src);
  try {
    db.prepare('INSERT INTO odometer_readings(id,vehicle_id,km,measured_at,source,recorded_by,created_at) VALUES (?,?,?,?,?,?,?)').run('tzuv-1', VID, 100000, iso(0.02), 'manuell', null, iso(0.02));
    db.prepare('INSERT INTO odometer_readings(id,vehicle_id,km,measured_at,source,recorded_by,created_at) VALUES (?,?,?,?,?,?,?)').run('tzuv-2', VID, 100500, iso(0.01), 'manuell', null, iso(0.01));
    db.prepare(`INSERT INTO cases(${cols.join(',')}) VALUES (${cols.map(() => '?').join(',')})`).run(...cols.map((c) => (c === 'id' ? 'tzuv-case' : c === 'case_no' ? 'TZUV-1' : c === 'request_key' ? 'tzuv-case' : c === 'vehicle_id' ? VID : c === 'duplicate_of' ? null : c === 'created_at' ? iso(0.01) : src[c])));
    db.prepare(`INSERT INTO parts(id,case_id,user_id,name,quantity,unit,unit_price_net,valuation,created_at) VALUES ('tzuv-p','tzuv-case',?,'Spiegel',1,'Stk',NULL,'unvalued',?)`).run(users.ws.id, iso(0.01));
    const ym = BERLIN_YM;
    const r = (await users.fleet.get(`/api/reports/costs?from=${ym}&to=${ym}&site=Unbewertet-Test`)).data;
    eq(r.rows.length, 1); eq(r.rows[0].valued_items, 0); eq(r.rows[0].unvalued_items, 1); eq(r.rows[0].actual_net, 0);
    eq(r.totals.valued_items, 0, 'Summe'); eq(r.totals.unvalued_items, 1);
    eq(r.sites.length, 1); eq(r.sites[0].valued_items, 0, 'Standort');
    const v = r.vehicles.find((x) => x.vehicle_id === VID); eq(v.km, 500); eq(v.valued_items, 0); eq(v.cost_per_km, null, 'ohne belegten Betrag kein Wert je km'); eq(v.complete, false);
    // nur Schätzung (19.10.2026: vorher „0,000 €/km“, complete true) → kein €/km, unvollständig
    db.prepare(`UPDATE parts SET valuation='estimate', unit_price_net=800 WHERE id='tzuv-p'`).run();
    { const r2 = (await users.fleet.get(`/api/reports/costs?from=${ym}&to=${ym}&site=Unbewertet-Test`)).data; const v2 = r2.vehicles.find((x) => x.vehicle_id === VID);
      eq(v2.estimate_net, 800); eq(v2.cost_per_km, null, 'nur Schätzung → kein €/km'); eq(v2.complete, false, 'Schätzung → unvollständig'); }
    db.prepare(`UPDATE parts SET valuation='unvalued', unit_price_net=NULL WHERE id='tzuv-p'`).run();
    const all = (await users.fleet.get(`/api/reports/costs?from=2026-01&to=${COST_TO}`)).data;
    eq(all.totals.valued_items, all.rows.reduce((s, x) => s + x.valued_items, 0), 'Summe = Zeilen');
    ok(all.rows.every((x) => x.valued_items > 0 || x.actual_net === 0), 'ohne belegte Position nie ein Ist-Betrag');
    eq((await users.fleet.get(`/api/cases/tzuv-case`)).data.costs.valued_items, 0, 'Vorgang');
    eq((await users.fleet.get(`/api/vehicles/${VID}`)).data.costs.valued_items, 0, 'Fahrzeugakte');
    const app = await (await import('node:fs/promises')).readFile(new URL('../public/app.js', import.meta.url), 'utf8');
    ok(/const eurIst = \(o\) => \(o && o\.valued_items === 0 && o\.unvalued_items > 0 \? '–' : eur\(o\.actual_net\)\)/.test(app), 'Oberfläche: „–“-Regel');
    eq((app.match(/eurIst\(/g) || []).length, 6, 'Vorgang, Fahrzeugakte, Summe, Standort, Fahrzeug, Monat');
    const i18n = await (await import('node:fs/promises')).readFile(new URL('../public/i18n.js', import.meta.url), 'utf8');
    for (const w of ['steht bei „Belegt“ „–“ statt 0 €', 'стоїть «–» замість 0 €', '“Documented” shows “–” instead of €0']) ok(i18n.includes(w), 'Hilfe: ' + w);
  } finally {
    db.prepare(`DELETE FROM parts WHERE id='tzuv-p'`).run(); db.prepare(`DELETE FROM case_events WHERE case_id='tzuv-case'`).run(); db.prepare(`DELETE FROM cases WHERE id='tzuv-case'`).run();
    db.prepare(`DELETE FROM odometer_readings WHERE id LIKE 'tzuv-%'`).run();
    await owner.post(`/api/vehicles/${VID}/active`, { active: false, reason: 'Testdaten unbewertet' });
  }
});

