    r = calc(L('ueber_12'), [], '2026-03-01');
    eq(r.hu.status, 'ungeklaert'); ok(/Keine durchgeführte HU/.test(r.hu.notes.join(' ')));
    // jeder Hinweis hat einen Code mit deutschem Gegenstück in der Oberfläche (UK/EN-Anzeige)
