  for (const p of paras) eq((p.match(/\d+/g) || []).map(Number).join(','), [...lim, 5].join(','), 'Zahlen in der Reihenfolge Fotos, Vorgang, Bußgeld, Dokumente, Hinweise, Rufnummern, MB');
