await test('Push-Wiederholung und Sammel-Push nach der Ruhezeit in der AKTUELLEN Sprache der Person (nicht der Sprache beim Ereignis); gespeicherter Text bleibt', async () => {
  const { retryFailedPush } = await import('../src/notify.js');
  const u = users.fleet;
  const kp = await crypto.subtle.generateKey({ name: 'ECDH', namedCurve: 'P-256' }, true, ['deriveBits']);
  const pub = new Uint8Array(await crypto.subtle.exportKey('raw', kp.publicKey));
  const authSecret = crypto.getRandomValues(new Uint8Array(16));
  const ep = 'https://push.example/ok/lang-' + rk();
  eq((await u.post('/api/push/subscribe', { endpoint: ep, keys: { p256dh: b64urlEncode(pub), auth: b64urlEncode(authSecret) } })).status, 200);
  const te = new TextEncoder();
  const hk = async (salt, ikm, info, bits) => new Uint8Array(await crypto.subtle.deriveBits({ name: 'HKDF', hash: 'SHA-256', salt, info }, await crypto.subtle.importKey('raw', ikm, 'HKDF', false, ['deriveBits']), bits));
  const decrypt = async (sent) => {
    const body = new Uint8Array(sent.init.body);
    const salt = body.slice(0, 16); const idlen = body[20]; const asPub = body.slice(21, 21 + idlen); const ct = body.slice(21 + idlen);
    const asKey = await crypto.subtle.importKey('raw', asPub, { name: 'ECDH', namedCurve: 'P-256' }, false, []);
    const shared = new Uint8Array(await crypto.subtle.deriveBits({ name: 'ECDH', public: asKey }, kp.privateKey, 256));
    const ikm = await hk(authSecret, shared, concatBytes(te.encode('WebPush: info\0'), pub, asPub), 256);
    const cek = await hk(salt, ikm, te.encode('Content-Encoding: aes128gcm\0'), 128);
    const nonce = await hk(salt, ikm, te.encode('Content-Encoding: nonce\0'), 96);
    const pt = new Uint8Array(await crypto.subtle.decrypt({ name: 'AES-GCM', iv: nonce }, await crypto.subtle.importKey('raw', cek, 'AES-GCM', false, ['decrypt']), ct));
    return JSON.parse(new TextDecoder().decode(pt.slice(0, -1)));
  };
  const sentMsgs = async () => Promise.all(env.pushLog.filter((p) => p.url === ep).map(decrypt));
  const ins = env.DB.prepare(`INSERT INTO notifications(id,environment,user_id,case_id,event_key,kind,urgent,title,body,created_at,push_status,push_attempts,push_hold_until) VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?)`);
  const old = new Date(Date.now() - 10 * 60000).toISOString();
  try {
    // (1) fehlgeschlagener Push auf Deutsch, Person stellt danach auf Englisch um → Wiederholung auf Englisch
    await ins.bind('pl-1', 'test', u.id, null, 'pl:1', 'released', 0, 'Fahrzeug technisch freigegeben', 'SM-2020-0101 · PL-XY 1 · kritisch · TEST', old, 'failed', 1, null).run();
    await ins.bind('pl-2', 'test', u.id, null, 'pl:2', 'agent', 0, 'Freier Titel', 'Freitext · kritisch', old, 'failed', 1, null).run();
    eq((await u.patch('/api/me', { language: 'en' })).status, 200);
    env.pushLog.length = 0;
    await retryFailedPush(env);
    let msgs = await sentMsgs();
    const m1 = msgs.find((m) => m.id === 'pl-1'); const m2 = msgs.find((m) => m.id === 'pl-2');
    ok(m1 && m2, 'beide wiederholt: ' + msgs.length);
    eq(m1.title, 'Vehicle technically released'); eq(m1.body, 'SM-2020-0101 · PL-XY 1 · critical · TEST');
    eq(m2.title, 'Freier Titel', 'Freitext bleibt'); eq(m2.body, 'Freitext · kritisch');
    eq((await env.DB.prepare("SELECT title, body, push_status FROM notifications WHERE id='pl-1'").first()).body, 'SM-2020-0101 · PL-XY 1 · kritisch · TEST', 'gespeicherter Text unverändert');
    // (2) Ruhezeit vorbei: Sammel-Push (ein Push, „· +1“) auf Ukrainisch, obwohl auf Deutsch gespeichert
    await ins.bind('pl-3', 'test', u.id, null, 'pl:3', 'inspection_defect', 0, 'Prüfung mit gefährlichen Mängeln', 'PL-XY 3 · UVV 05.01.2020: verkehrsunsicher – nicht einplanen · TEST', old, 'pending', 0, new Date(Date.now() - 60000).toISOString()).run();
    await ins.bind('pl-4', 'test', u.id, null, 'pl:4', 'comment', 0, 'Neuer Kommentar', 'SM-2020-0104 · PL-XY 4 · niedrig', new Date(Date.now() - 9 * 60000).toISOString(), 'pending', 0, new Date(Date.now() - 60000).toISOString()).run();
    eq((await u.patch('/api/me', { language: 'uk' })).status, 200);
    env.pushLog.length = 0;
    await retryFailedPush(env);
    msgs = await sentMsgs();
    eq(msgs.length, 1, 'ein Sammel-Push');
    eq(msgs[0].title, 'Огляд із небезпечними дефектами'); eq(msgs[0].body, 'PL-XY 3 · UVV 05.01.2020: небезпечний для руху – не планувати · TEST · +1');
    const st = (await env.DB.prepare("SELECT id, push_status FROM notifications WHERE id IN ('pl-3','pl-4')").all()).results;
    ok(st.every((r) => r.push_status === 'accepted'), 'beide zugestellt');
    // Hilfe „Push“ erklärt die Sprache in allen drei Sprachen (mit dem echten Menünamen)
    const { STRINGS } = await import('../public/i18n.js');
    for (const l of ['de', 'uk', 'en']) { const last = STRINGS[l].help_push_s.split('|').at(-1); ok(last.includes(STRINGS[l].nav_profile) && last.includes(STRINGS[l].language), `Hilfe Sprache ${l}`); }
  } finally {
    await u.patch('/api/me', { language: 'de' });
    await env.DB.prepare("DELETE FROM notifications WHERE id LIKE 'pl-%'").run();
    env.DB.db.prepare('DELETE FROM push_subscriptions WHERE endpoint=?').run(ep);
  }
});

await test('Push-Inhalt nennt die Sprache des Textes (lang) und den Zeitpunkt des Ereignisses (ts) – Gerät liest richtig vor; Nachholen: übersetzt = aktuelle Sprache, Freitext = gespeicherte Sprache, unbekannt = ohne Angabe', async () => {
  const { retryFailedPush } = await import('../src/notify.js');
  const u = users.fleet;
  const kp = await crypto.subtle.generateKey({ name: 'ECDH', namedCurve: 'P-256' }, true, ['deriveBits']);
  const pub = new Uint8Array(await crypto.subtle.exportKey('raw', kp.publicKey));
  const authSecret = crypto.getRandomValues(new Uint8Array(16));
  const ep = 'https://push.example/ok/plang-' + rk();
  eq((await u.post('/api/push/subscribe', { endpoint: ep, keys: { p256dh: b64urlEncode(pub), auth: b64urlEncode(authSecret) } })).status, 200);
  const te = new TextEncoder();
  const hk = async (salt, ikm, info, bits) => new Uint8Array(await crypto.subtle.deriveBits({ name: 'HKDF', hash: 'SHA-256', salt, info }, await crypto.subtle.importKey('raw', ikm, 'HKDF', false, ['deriveBits']), bits));
  const decrypt = async (sent) => {
    const body = new Uint8Array(sent.init.body);
    const salt = body.slice(0, 16); const idlen = body[20]; const asPub = body.slice(21, 21 + idlen); const ct = body.slice(21 + idlen);
    const asKey = await crypto.subtle.importKey('raw', asPub, { name: 'ECDH', namedCurve: 'P-256' }, false, []);
    const shared = new Uint8Array(await crypto.subtle.deriveBits({ name: 'ECDH', public: asKey }, kp.privateKey, 256));
    const ikm = await hk(authSecret, shared, concatBytes(te.encode('WebPush: info\0'), pub, asPub), 256);
    const cek = await hk(salt, ikm, te.encode('Content-Encoding: aes128gcm\0'), 128);
    const nonce = await hk(salt, ikm, te.encode('Content-Encoding: nonce\0'), 96);
    const pt = new Uint8Array(await crypto.subtle.decrypt({ name: 'AES-GCM', iv: nonce }, await crypto.subtle.importKey('raw', cek, 'AES-GCM', false, ['decrypt']), ct));
    return JSON.parse(new TextDecoder().decode(pt.slice(0, -1)));
  };
  const sentMsgs = async () => Promise.all(env.pushLog.filter((p) => p.url === ep).map(decrypt));
  const ins = env.DB.prepare(`INSERT INTO notifications(id,environment,user_id,case_id,event_key,kind,urgent,title,body,created_at,push_status,push_attempts,lang) VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?)`);
  const old = new Date(Date.now() - 10 * 60000).toISOString();
  try {
    // (1) Testbenachrichtigung auf Ukrainisch → Push mit lang 'uk', gespeichert mit Sprache
    eq((await u.patch('/api/me', { language: 'uk' })).status, 200);
    env.pushLog.length = 0;
    eq((await u.post('/api/push/test', {})).status, 200);
    let msgs = await sentMsgs();
    eq(msgs.length, 1, 'ein Test-Push'); ok(Math.abs(msgs[0].ts - Date.now()) < 60000, 'ts beim Sofortversand ≈ jetzt'); eq(msgs[0].kind, 'test', 'Art im Push (Klickziel)'); eq(msgs[0].lang, 'uk', 'Sprache im Push ' + JSON.stringify(msgs[0])); eq(msgs[0].title, nt('uk', 'test'));
    eq((await env.DB.prepare('SELECT lang FROM notifications WHERE id=?').bind(msgs[0].id).first()).lang, 'uk', 'Sprache gespeichert');
    // (2) Vorgangs-Hinweis an die Fuhrparkleitung (englisch) → lang 'en'
    eq((await u.patch('/api/me', { language: 'en' })).status, 200);
    env.pushLog.length = 0;
    const cr = await users.driver.post('/api/cases', { vehicle_id: V1, description: 'Push-Sprachtest', priority: 'kritisch', driveability: 'fahrbereit', workshop_site: 'DORTMUND', request_key: rk() });
    ok(cr.status === 200 || cr.status === 201, 'Vorgang angelegt: ' + cr.status);
    msgs = await sentMsgs();
    ok(msgs.length >= 1 && msgs.every((m) => m.lang === 'en'), 'Vorgangs-Push englisch ausgezeichnet: ' + JSON.stringify(msgs.map((m) => [m.lang, m.title])));
    // (3) Nachholen nach Sprachwechsel auf Englisch: übersetzter Text → 'en'; deutscher Freitext → bleibt 'de'; alter Hinweis ohne Sprache, Freitext → ohne Angabe
    await ins.bind('pg-1', 'test', u.id, null, 'pg:1', 'released', 0, 'Fahrzeug technisch freigegeben', 'SM-2020-0201 · PG-XY 1 · kritisch · TEST', old, 'failed', 1, 'de').run();
    await ins.bind('pg-2', 'test', u.id, null, 'pg:2', 'agent', 0, 'Freier Titel', 'Freitext', old, 'failed', 1, 'de').run();
    await ins.bind('pg-3', 'test', u.id, null, 'pg:3', 'agent', 0, 'Alter Freitext', 'ohne Sprache', old, 'failed', 1, null).run();
    await ins.bind('pg-4', 'test', u.id, null, 'pg:4', 'agent', 0, 'Free title', 'already English', old, 'failed', 1, 'en').run();
    env.pushLog.length = 0;
    await retryFailedPush(env);
    msgs = await sentMsgs();
    const by = Object.fromEntries(msgs.map((m) => [m.id, m]));
    ok(by['pg-1'] && by['pg-2'] && by['pg-3'] && by['pg-4'], 'alle wiederholt: ' + msgs.map((m) => m.id));
    eq(by['pg-1'].lang, 'en'); eq(by['pg-1'].title, 'Vehicle technically released');
    eq(by['pg-2'].lang, 'de', 'Freitext bleibt deutsch ausgezeichnet'); eq(by['pg-2'].title, 'Freier Titel');
    ok(!('lang' in by['pg-3']), 'unbekannte Sprache → keine Angabe');
    eq(by['pg-4'].lang, 'en', 'schon in aktueller Sprache');
    // Zeitpunkt des Ereignisses im Push (ts): nachgeholter Push zeigt die echte Uhrzeit, nicht die Zustellzeit
    ok(['pg-1', 'pg-2', 'pg-3', 'pg-4'].every((id) => by[id].ts === Date.parse(old)), 'ts = Zeitpunkt des Ereignisses: ' + JSON.stringify(msgs.map((m) => m.ts)));
    // Service Worker übergibt die Sprache an die Mitteilung
    const sw = (await import('node:fs')).readFileSync(new URL('../public/sw.js', import.meta.url), 'utf8');
    ok(/lang: d\.lang/.test(sw) && /timestamp: d\.ts/.test(sw), 'sw.js setzt lang und timestamp der Mitteilung');
    ok(sw.includes("d.kind === 'new_login' ? '#/more?o=sess'"), 'Klick auf Anmelde-Hinweis öffnet „Meine Anmeldungen“ wie die Hinweisliste');
    ok(sw.includes('ref: d.ref') && /\^\(vehicle\|fine\):/.test(sw), 'Push-Klick folgt dem Bezug (Fahrzeugakte/Bußgeld)');
    // Hilfe „Push“ erklärt das Ziel beim Tippen mit dem echten Menünamen (DE/UK/EN)
    const { STRINGS } = await import('../public/i18n.js');
    for (const l of ['de', 'uk', 'en']) ok(STRINGS[l].help_push_s.split('|').some((x) => x.includes(STRINGS[l].my_sessions)), `Hilfe Tippen-Ziel ${l}`);
    ok((await import('node:fs')).readFileSync(new URL('../public/app.js', import.meta.url), 'utf8').includes("x.kind === 'new_login' ? '#/more?o=sess'"), 'Hinweisliste nutzt dasselbe Ziel');
  } finally {
    await u.patch('/api/me', { language: 'de' });
    await env.DB.prepare("DELETE FROM notifications WHERE id LIKE 'pg-%'").run();
    env.DB.db.prepare('DELETE FROM push_subscriptions WHERE endpoint=?').run(ep);
  }
});

await test('Fahrzeugakte: Fahrleistung je Monat nur aus gespeicherten Ablesungen (Berliner Monat, mehrere Monate gekennzeichnet, Rückgang ohne Wert)', async () => {
  const { mileageByMonth } = await import('../src/vehicles.js');
  const M = ['2026-10', '2026-09', '2026-08', '2026-07', '2026-06'];
  const R = [{ km: 100000, measured_at: '2026-06-10T12:00:00.000Z' }, { km: 101000, measured_at: '2026-07-31T22:30:00.000Z' }, { km: 102000, measured_at: '2026-08-20T12:00:00.000Z' }, { km: 105000, measured_at: '2026-10-05T12:00:00.000Z' }];
  const x = mileageByMonth(R, M);
  eq(x.map((r) => r.status).join('/'), 'ok/no_reading/ok/no_reading/no_previous', 'Status je Monat (31.07. 22:30 UTC = 1.8. Berlin)');
  eq(x[4].to_km, 100000, 'erste Ablesung ohne Vorwert: kein Monatswert'); eq(x[4].km, null);
  eq(x[2].km, 2000, 'August: 102000 − 100000 (Juni)'); eq(x[2].spans, true, 'August umfasst Juli mit'); eq(x[2].readings, 2, 'zwei Ablesungen im August');
  eq(x[0].km, 3000, 'Oktober: 105000 − 102000'); eq(x[0].spans, true, 'Oktober umfasst September mit');
  const y = mileageByMonth([...R, { km: 104900, measured_at: '2026-10-20T12:00:00.000Z' }], M);
  eq(y[0].status, 'decrease', 'Rückgang im Monat → kein Wert'); eq(y[0].km, null);
  const z = mileageByMonth([{ km: 5, measured_at: '2026-09-30T12:00:00.000Z' }, { km: 905, measured_at: '2026-10-02T12:00:00.000Z' }], M);
  eq(z[0].km, 900); eq(z[0].spans, false, 'Vorwert im Vormonat: kein Hinweis');
  // über die API: Ablesung im Vormonat und heute
  eq((await owner.post('/api/vehicles', { plate: 'KP-FL 1', vin: 'WDB96340310555577', site: 'Dortmund' })).status, 201);
  const VK = 'VIN:WDB96340310555577'; const { addMonths } = await import('../src/util.js');
  const prev = addMonths(`${BERLIN_YM}-10`, -1);
  eq((await users.fleet.post(`/api/vehicles/${VK}/odometer`, { km: 200000, measured_on: prev })).status, 201);
  eq((await users.fleet.post(`/api/vehicles/${VK}/odometer`, { km: 203500 })).status, 201);
  const ml = (await users.fleet.get(`/api/vehicles/${VK}`)).data.mileage;
  ok(ml && ml.months.length === 12 && ml.max_months === 12, '12 Monate');
  eq(ml.months[0].month, BERLIN_YM); eq(ml.months[0].km, 3500, 'laufender Monat 3500 km'); eq(ml.months[0].spans, false);
  eq(ml.months[1].status, 'no_previous', 'Vormonat: erste Ablesung'); eq(ml.total_km, 3500, 'Summe');
  ok((await users.ws.get(`/api/vehicles/${VK}`)).data.mileage, 'Werkstatt sieht die Fahrleistung (Fahrzeugdaten, keine Personen)');
  ok(!('mileage' in (await users.fleet.get(`/api/vehicles/${VK}/timeline`)).data), 'Zeitleiste ohne Monatsübersicht');
  // Rückgang mit Begründung → kein Wert, keine Summe
  eq((await users.fleet.post(`/api/vehicles/${VK}/odometer`, { km: 150, note: 'Tachotausch (Test)' })).status, 201);
  const m2 = (await users.fleet.get(`/api/vehicles/${VK}`)).data.mileage;
  eq(m2.months[0].status, 'decrease'); eq(m2.total_km, null, 'mit Rückgang keine Summe');
  eq((await owner.post(`/api/vehicles/${VK}/active`, { active: false, reason: 'Testdaten Fahrleistung' })).status, 200);
});

await test('km-Zähler gesunken (Tachotausch): km-Fälligkeit „ungeklärt“ statt falscher Restlaufleistung, km-Kontingent ohne Wert, Agent-Hinweis, Auflösung durch Durchführung', async () => {
  const { kmDue, parseKmDrop, kmCounterDropAfter } = await import('../src/maintenance.js');
  const { renderFindingMessage } = await import('../public/finding-messages.js');
  const day = (n) => new Date(Date.parse(BERLIN_TODAY + 'T00:00:00Z') + n * 86400000).toISOString().slice(0, 10);
  // Rechenkern
  const rule = { interval_km: 50000, last_done_km: 280000, updated_at: '2026-10-01T10:00:00.000Z' };
  eq(kmDue(rule, { km: 1200, measured_at: '2026-10-05T12:00:00.000Z' }, null).km_remaining, 328800, 'ohne Rücksprung-Angabe: bisheriges Verhalten');
  const k = kmDue(rule, { km: 1200, measured_at: '2026-10-05T12:00:00.000Z', drop_at: '2026-10-05T12:00:00.000Z', drop_rec: '2026-10-05T12:00:01.000Z' }, null);
  eq(k.km_status, 'ungeklaert'); eq(k.km_unclear, 'counter_drop'); eq(k.km_remaining, null, 'keine Restlaufleistung aus gemischten Zählerständen'); eq(k.next_due_km, 330000);
  ok(!kmCounterDropAfter({ ...rule, updated_at: '2026-10-06T08:00:00.000Z' }, { drop_at: '2026-10-05T12:00:00.000Z', drop_rec: '2026-10-05T12:00:01.000Z' }), 'Regel danach geändert → wieder berechnet');
  ok(kmCounterDropAfter({ ...rule, updated_at: '2026-10-06T08:00:00.000Z' }, { drop_at: '2026-10-01T12:00:00.000Z', drop_rec: '2026-10-07T09:00:00.000Z' }), 'nachträglich datierter Rücksprung zählt ab Erfassung');
  eq(JSON.stringify(parseKmDrop(null)), '{"drop_at":null,"drop_rec":null}');
  ok(/ungeklärt.*Tachotausch/.test(renderFindingMessage('MAINT_KM_UNCLEAR', { plate: 'X', kind: 'Öl', date: '2026-10-05' }, 'de')), 'Befundtext DE');
  ok(renderFindingMessage('MAINT_KM_UNCLEAR', { plate: 'X', kind: 'Öl', date: '2026-10-05' }, 'en', { dates: true }).includes('05/10/2026'), 'Befundtext EN mit Datum je Sprache');
  ok(renderFindingMessage('MAINT_KM_UNCLEAR', { plate: 'X', kind: 'Öl', date: '2026-10-05' }, 'uk', { dates: true }).includes('05.10.2026'), 'Befundtext UK');
  // über die API
  eq((await owner.post('/api/vehicles', { plate: 'KP-TT 1', vin: 'WDB96340310555579', site: 'Dortmund' })).status, 201);
  const V = 'VIN:WDB96340310555579'; const vp = `/api/vehicles/${V}`;
  eq((await users.fleet.post(`${vp}/odometer`, { km: 300000, measured_on: day(-40) })).status, 201);
  const r = await users.fleet.post(`${vp}/maintenance`, { kind: 'Ölwechsel', interval_km: 50000, last_done_km: 280000, evidence: 'Testnachweis Tachotausch' });
  eq(r.status, 201);
  const c = await users.fleet.post(`${vp}/contracts`, { kind: 'leasing', partner: 'Test-Leasing', start_date: day(-60), end_date: day(600), km_allowance: 200000, start_km: 250000, evidence: 'Testvertrag Tachotausch' });
  eq(c.status, 201);
  let row = (await users.fleet.get('/api/maintenance')).data.rows.find((x) => x.id === r.data.id);
  eq(row.km_status, 'ok'); eq(row.km_remaining, 30000, 'vor dem Tausch normal');
  // Tachotausch: neuer Zähler (nachträglich datiert, mit Begründung), danach weitere Ablesung
  eq((await users.fleet.post(`${vp}/odometer`, { km: 1200, measured_on: day(-3), note: 'Tachotausch laut Werkstattrechnung (Test)' })).status, 201);
  eq((await users.fleet.post(`${vp}/odometer`, { km: 2400 })).status, 201);
  let ov = (await users.fleet.get('/api/maintenance')).data;
  row = ov.rows.find((x) => x.id === r.data.id);
  eq(row.status, 'ungeklaert', 'Gesamtstatus Frist ungeklärt'); eq(row.km_status, 'ungeklaert'); eq(row.km_unclear, 'counter_drop');
  eq(row.km_remaining, null, 'vorher fälschlich 327 600 km Rest'); ok(row.km_drop_at && row.km_drop_at.startsWith(day(-3)), 'Datum des Rücksprungs'); eq(row.km_forecast, null, 'keine Prognose über den Rücksprung');
  ok(ov.totals.unclear >= 1, 'Zähler „ungeklärt“');
  let d = (await users.fleet.get(vp)).data;
  const m = d.maintenance.find((x) => x.id === r.data.id);
  eq(m.km_unclear, 'counter_drop', 'Fahrzeugakte kennzeichnet die Regel'); ok(!('drop_at' in d.odometer[0]), 'Ablesungen ohne Hilfsspalte');
  const ct = d.contracts.find((x) => x.id === c.data.id);
  eq(ct.status.km.status, 'zaehler', 'Kontingent nicht berechenbar'); eq(ct.status.overall, 'hinweis'); ok(!('driven' in ct.status.km), 'keine gefahrenen km aus gemischten Zählern');
  eq((await users.fleet.get('/api/contracts?filter=aktion')).data.contracts.find((x) => x.id === c.data.id).status.km.status, 'zaehler', 'Übersicht gleich');
  await users.fleet.post('/api/agent/run');
  let fs = (await users.fleet.get('/api/master')).data.findings;
  const f = fs.find((x) => x.finding_code === 'INSPECTION_UNCLEAR' && x.subject_key === `${r.data.id}|km|zaehler`);
  ok(f && /KP-TT 1: Ölwechsel – Fälligkeit nach km ungeklärt/.test(f.message), 'Agent-Hinweis: ' + (f && f.message));
  ok(!fs.some((x) => x.subject_key === `${r.data.id}|km` && ['MAINTENANCE_DUE', 'MAINTENANCE_OVERDUE'].includes(x.finding_code)), 'keine km-Fälligkeit aus gemischten Zählern');
  // Auflösung: Durchführung mit km-Stand des neuen Zählers
  eq((await users.fleet.post(`/api/maintenance/${r.data.id}/complete`, { done_date: BERLIN_TODAY, evidence: 'Ölwechsel nach Tachotausch (Test)', done_km: 2400 })).status, 200);
  row = (await users.fleet.get('/api/maintenance')).data.rows.find((x) => x.id === r.data.id);
  eq(row.km_status, 'ok'); eq(row.next_due_km, 52400); eq(row.km_remaining, 50000, 'neuer Zyklus auf dem neuen Zähler'); ok(!row.km_unclear);
  await users.fleet.post('/api/agent/run');
  fs = (await users.fleet.get('/api/master')).data.findings;
  ok(!fs.some((x) => x.subject_key === `${r.data.id}|km|zaehler`), 'Hinweis erledigt sich');
  // Vertrag beginnt nach dem Tausch → normal berechnet
  const c2 = await users.fleet.post(`${vp}/contracts`, { kind: 'wartung', partner: 'Test-Service', start_date: BERLIN_TODAY, end_date: day(400), km_allowance: 100000, start_km: 2400, evidence: 'Testvertrag 2' });
  eq(c2.status, 201);
  d = (await users.fleet.get(vp)).data;
  eq(d.contracts.find((x) => x.id === c2.data.id).status.km.status, 'ok', 'Vertrag nach dem Tausch: normal');
  // Oberfläche: Texte in drei Sprachen
  const { STRINGS } = await import('../public/i18n.js');
  for (const l of ['de', 'uk', 'en']) for (const key of ['km_unclear_drop', 'ct_km_counter_drop']) ok(STRINGS[l][key] && STRINGS[l][key].includes('{d}'), `${l}.${key}`);
  const app = (await import('node:fs')).readFileSync(new URL('../public/app.js', import.meta.url), 'utf8');
  ok(app.includes("t('km_unclear_drop')") && app.includes("s.km.status === 'zaehler'"), 'Akte, Prüftermine und Verträge zeigen den Hinweis');
  eq((await owner.post(`${vp}/active`, { active: false, reason: 'Testdaten Tachotausch' })).status, 200);
});

await test('km-Plausibilität bei „Prüfung erledigt“ (kleiner als zuvor erfasst → abgewiesen) und Datenqualität: km-Rücksprung ohne Begründung gemeldet, begründete nicht', async () => {
  const day = (n) => new Date(Date.parse(BERLIN_TODAY + 'T00:00:00Z') + n * 86400000).toISOString().slice(0, 10);
  eq((await owner.post('/api/vehicles', { plate: 'KP-TT 2', vin: 'WDB96340310555580', site: 'Dortmund' })).status, 201);
  const V = 'VIN:WDB96340310555580'; const vp = `/api/vehicles/${V}`;
  eq((await users.fleet.post(`${vp}/odometer`, { km: 100000, measured_on: day(-10) })).status, 201);
  let dq = (await users.fleet.get('/api/admin/data-quality')).data;
  ok(!dq.items.some((i) => i.check === 'km_drop_unexplained' && i.vehicle_id === V), 'ohne Rücksprung kein Befund');
  const r = await users.fleet.post(`${vp}/maintenance`, { kind: 'Ölwechsel', interval_km: 50000, last_done_km: 90000, evidence: 'DQ-Test' });
  // „Prüfung erledigt“ mit km kleiner als der zuvor erfasste: abgewiesen (Tippfehler), Text übersetzt
  const rej = await users.fleet.post(`/api/maintenance/${r.data.id}/complete`, { done_date: BERLIN_TODAY, evidence: 'Tippfehler-Test', done_km: 10000 });
  eq(rej.status, 400, 'kleinerer km-Stand abgewiesen'); ok(/kleiner als ein zuvor erfasster km-Stand/.test(rej.data.message || rej.data.error || JSON.stringify(rej.data)), 'Meldung');
  const { translateValidation } = await import('../public/i18n.js');
  ok(translateValidation('en', 'Kilometerstand bei Durchführung ist kleiner als ein zuvor erfasster km-Stand. Bitte prüfen; bei Tachotausch zuerst den neuen km-Stand mit Begründung in der Fahrzeugakte erfassen.'), 'Meldung übersetzt');
  // nachträglich datierte Durchführung mit zu großem km-Stand (vor der Ablesung vom Tag −10) → die spätere Ablesung ist ein Rücksprung ohne Begründung
  // seit 17.10.2026 weist „erledigt“ das ab (größer als der spätere Stand); den Rücksprung erzeugt hier ein begründeter Nachtrag in der Akte
  eq((await users.fleet.post(`/api/maintenance/${r.data.id}/complete`, { done_date: day(-20), evidence: 'Tippfehler-Test', done_km: 150000 })).status, 400, 'größer als späterer Stand abgewiesen');
  eq((await users.fleet.post(`${vp}/odometer`, { km: 150000, measured_on: day(-20), note: 'Nachtrag laut Werkstattrechnung' })).status, 201);
  dq = (await users.fleet.get('/api/admin/data-quality')).data;
  let f = dq.items.find((i) => i.check === 'km_drop_unexplained' && i.vehicle_id === V);
  ok(f && f.severity === 'hinweis' && f.detail === `${day(-10)}: 150000 → 100000 km · manuell:fleet`, 'Befund mit Datum, Werten und Quelle: ' + (f && f.detail));
  // begründeter Rücksprung (Tachotausch) zählt nicht; der unbegründete bleibt gemeldet
  eq((await users.fleet.post(`${vp}/odometer`, { km: 500, note: 'Tachotausch (Test)' })).status, 201);
  dq = (await users.fleet.get('/api/admin/data-quality')).data;
  f = dq.items.find((i) => i.check === 'km_drop_unexplained' && i.vehicle_id === V);
  ok(f && !/×/.test(f.detail), 'nur der unbegründete, ohne Anzahl');
  const { STRINGS } = await import('../public/i18n.js');
  for (const l of ['de', 'uk', 'en']) ok(STRINGS[l].dq_km_drop_unexplained, `Bezeichnung ${l}`);
  eq((await owner.post(`${vp}/active`, { active: false, reason: 'Testdaten DQ' })).status, 200);
  dq = (await users.fleet.get('/api/admin/data-quality')).data;
  ok(!dq.items.some((i) => i.vehicle_id === V), 'außer Betrieb: kein Befund');
});

await test('km-Zähler gesunken: Fahrer-Ansicht „Meine Fahrzeuge“ zeigt keine km-Fälligkeit aus gemischten Zählern (gleiche Regel wie Übersicht), nach Durchführung wieder', async () => {
  const day = (n) => new Date(Date.parse(BERLIN_TODAY + 'T00:00:00Z') + n * 86400000).toISOString().slice(0, 10);
  eq((await owner.post('/api/vehicles', { plate: 'KP-TT 4', vin: 'WDB96340310555582', site: 'Dortmund' })).status, 201);
  const V = 'VIN:WDB96340310555582'; const vp = `/api/vehicles/${V}`;
  eq((await users.fleet.post(`${vp}/odometer`, { km: 360000, measured_on: day(-40) })).status, 201);
  const r = await users.fleet.post(`${vp}/maintenance`, { kind: 'Ölwechsel', interval_km: 10000, last_done_km: 340000, evidence: 'Testnachweis Fahrer-Tachotausch' });
  eq(r.status, 201);
  eq((await users.fleet.post(`${vp}/drivers`, { user_id: users.driver.id, end_previous: false })).status, 201);
  const myV = async () => (await users.driver.get('/api/me/vehicles')).data.vehicles.find((v) => v.plate === 'KP-TT 4');
  let mv = await myV();
  eq(JSON.stringify(mv.km_due.map((x) => [x.kind, x.km_remaining, x.status])), JSON.stringify([['Ölwechsel', -10000, 'ueberfaellig']]), 'vor dem Tausch: überschritten');
  // gebrauchter Ersatz-Tacho mit niedrigerem Stand (Rücksprung 360 000 → 355 000): Rest aus gemischten Zählern wäre −5 000 „überfällig“
  eq((await users.fleet.post(`${vp}/odometer`, { km: 355000, measured_on: day(-2), note: 'Tachotausch laut Werkstattrechnung (Test Fahrer)' })).status, 201);
  const row = (await users.fleet.get('/api/maintenance')).data.rows.find((x) => x.id === r.data.id);
  eq(row.km_status, 'ungeklaert', 'Übersicht: ungeklärt');
  mv = await myV();
  eq(mv.km_due.length, 0, 'Fahrer: keine Fälligkeit aus gemischten Zählern (vorher −5 000 km „überfällig“)');
  eq(JSON.stringify(Object.keys(mv.last_km).sort()), JSON.stringify(['km', 'measured_at', 'vehicle_id']), 'letzter km-Stand ohne Hilfsspalten');
  eq(mv.last_km.km, 355000);
  // Durchführung mit neuem km-Stand → Regel wieder berechnet, Fahrer sieht nichts (weit entfernt)
  eq((await users.fleet.post(`/api/maintenance/${r.data.id}/complete`, { done_date: BERLIN_TODAY, done_km: 355100, evidence: 'Ölwechsel nach Tachotausch (Test Fahrer)' })).status, 200);
  const warn = Number((await users.fleet.get('/api/maintenance')).data.rows.find((x) => x.id === r.data.id).km_remaining);
  eq(warn, 10000, 'Übersicht: wieder berechnet (355 100 + 10 000 − 355 100)');
  eq((await myV()).km_due.length, 0, 'ohne Vorwarnung: nicht überschritten → nichts');
  eq((await owner.put('/api/settings', { maintenance_warn_km: 15000 })).status, 200);
  try {
    mv = await myV();
    eq(JSON.stringify(mv.km_due.map((x) => [x.kind, x.km_remaining, x.status])), JSON.stringify([['Ölwechsel', 10000, 'faellig']]), 'Fahrer: gleiche Rechnung wie Übersicht');
  } finally { await owner.put('/api/settings', { maintenance_warn_km: null }); }
});

await test('km-Zähler gesunken + Datum bald fällig: Werkstattplan „Fällig – ohne Termin“ zeigt die Prüfung weiter (Status nach Datum, km ungeklärt gekennzeichnet), Prüftermine „ohne Termin“ ebenso', async () => {
  const day = (n) => new Date(Date.parse(BERLIN_TODAY + 'T00:00:00Z') + n * 86400000).toISOString().slice(0, 10);
  eq((await owner.post('/api/vehicles', { plate: 'KP-TT 3', vin: 'WDB96340310555581', site: 'Dortmund' })).status, 201);
  const V = 'VIN:WDB96340310555581'; const vp = `/api/vehicles/${V}`;
  eq((await users.fleet.post(`${vp}/odometer`, { km: 300000, measured_on: day(-40) })).status, 201);
  const soon = await users.fleet.post(`${vp}/maintenance`, { kind: 'Ölwechsel', interval_km: 50000, last_done_km: 280000, next_due_date: day(10), evidence: 'Test Datum+km 1' });
  const late = await users.fleet.post(`${vp}/maintenance`, { kind: 'Bremsen', interval_km: 100000, last_done_km: 250000, next_due_date: day(-2), evidence: 'Test Datum+km 2' });
  const fine = await users.fleet.post(`${vp}/maintenance`, { kind: 'Inspektion', interval_km: 100000, last_done_km: 250000, next_due_date: day(300), evidence: 'Test Datum+km 3' });
  for (const x of [soon, late, fine]) eq(x.status, 201, JSON.stringify(x.data));
  eq((await users.fleet.post(`${vp}/odometer`, { km: 1200, note: 'Tachotausch laut Werkstattrechnung (Test)' })).status, 201);
  const ov = (await users.fleet.get('/api/maintenance')).data;
  const row = (id) => ov.rows.find((x) => x.id === id);
  eq(row(soon.data.id).status, 'ungeklaert', 'Gesamtstatus: km ungeklärt überdeckt „bald fällig“'); eq(row(soon.data.id).date_status, 'faellig', 'Datumsstatus getrennt');
  eq(row(late.data.id).status, 'ueberfaellig'); eq(row(late.data.id).date_status, 'ueberfaellig'); eq(row(late.data.id).km_unclear, 'counter_drop');
  eq(row(fine.data.id).date_status, 'ok');
  // Fahrzeugliste, CSV und Integrations-API: kleinste km-Fälligkeit ohne Rest aus gemischten Zählern (vorher 328 800 km „Rest“)
  let lv = (await users.fleet.get('/api/vehicles')).data.vehicles.find((x) => x.id === V);
  eq(lv.next_due_km, 330000); eq(lv.km_remaining, null, 'Liste: kein Rest'); eq(lv.km_unclear, 'counter_drop'); ok(lv.km_drop_at, 'Liste: Datum');
  const vcsv = (await users.fleet.get('/api/vehicles?format=csv')).data; const vcsvT = typeof vcsv === 'string' ? vcsv : new TextDecoder().decode(vcsv);
  const vline = vcsvT.split('\n').find((l) => l.startsWith('KP-TT 3;')); ok(vline && /;330000;Ölwechsel;;/.test(vline), 'CSV: Rest-km leer: ' + vline);
  const iav = await anon.req('GET', '/api/integration/v1/availability?environment=test', undefined, { authorization: 'Bearer integration-token-xyz' });
  const iv = iav.data.vehicles.find((x) => x.id === V); eq(iv.km_remaining, null, 'Integration: kein Rest'); eq(iv.km_unclear, 'counter_drop');
  ok(iav.data.vehicles.filter((x) => x.id !== V).every((x) => x.km_unclear === null), 'andere Fahrzeuge: km_unclear null');
  let p = (await users.fleet.get('/api/workshop/plan?days=14')).data;
  const md = (id) => p.maintenance_due.find((x) => x.id === id);
  ok(md(soon.data.id), 'bald fällig nach Datum bleibt einzuplanen (vorher verschwunden)');
  eq(md(soon.data.id).status, 'faellig', 'Status nach Datum'); eq(md(soon.data.id).km_unclear, 'counter_drop'); eq(md(soon.data.id).km_remaining, null, 'keine Restlaufleistung');
  ok(md(soon.data.id).km_drop_at, 'Datum des Rücksprungs'); eq(md(soon.data.id).by_km, false, 'nicht „nach km fällig“');
  eq(md(late.data.id).status, 'ueberfaellig'); eq(md(late.data.id).km_unclear, 'counter_drop', 'überfällig: km-Hinweis mitgeliefert');
  ok(!md(fine.data.id), 'Datum in Ordnung + km ungeklärt: nicht im Plan (steht unter „Frist ungeklärt“)');
  // geplanter Termin im Zeitraum: Planeintrag trägt die Kennzeichnung, „ohne Termin“ entfällt
  eq((await users.fleet.post(`/api/maintenance/${soon.data.id}/plan`, { planned_date: day(3) })).status, 200);
  p = (await users.fleet.get('/api/workshop/plan?days=14')).data;
  ok(!md(soon.data.id), 'mit Termin nicht mehr ohne Termin');
  const it = p.days.flatMap((d) => d.items).find((i) => i.type === 'maintenance' && i.id === soon.data.id);
  ok(it && it.km_unclear === 'counter_drop' && it.km_remaining === null, 'Planeintrag gekennzeichnet');
  // Termin planen ändert die km-Grundlage nicht → bleibt ungeklärt (vorher: updated_at neu → wieder 328 800 km „Rest“ aus gemischten Zählern)
  const r2 = (await users.fleet.get('/api/maintenance')).data.rows.find((x) => x.id === soon.data.id);
  eq(r2.km_status, 'ungeklaert', 'nach dem Planen weiter ungeklärt'); eq(r2.km_remaining, null);
  eq((await users.fleet.get(vp)).data.maintenance.find((x) => x.id === soon.data.id).km_unclear, 'counter_drop', 'Akte ebenso');
  await users.fleet.post('/api/agent/run');
  ok((await users.fleet.get('/api/master')).data.findings.some((x) => x.subject_key === `${soon.data.id}|km|zaehler`), 'Agent-Hinweis bleibt nach dem Planen');
  // Auflösung weiter durch Durchführung mit neuem km-Stand
  eq((await users.fleet.post(`/api/maintenance/${soon.data.id}/complete`, { done_date: BERLIN_TODAY, evidence: 'Ölwechsel (Test)', done_km: 1200 })).status, 200);
  const r3 = (await users.fleet.get('/api/maintenance')).data.rows.find((x) => x.id === soon.data.id);
  eq(r3.km_status, 'ok'); eq(r3.km_remaining, 50000); ok(!r3.km_unclear);
  lv = (await users.fleet.get('/api/vehicles')).data.vehicles.find((x) => x.id === V);
  eq(lv.next_due_km, 51200); eq(lv.km_remaining, 50000, 'Liste nach Durchführung wieder mit Rest'); ok(!lv.km_unclear);
  const app = (await import('node:fs')).readFileSync(new URL('../public/app.js', import.meta.url), 'utf8');
  ok(/const noPlan = \(r\) => \([^\n]*kmUnclearDateDue\(r\)/.test(app), 'Prüftermine „Fällig ohne Termin“ nutzt dieselbe Regel');
  ok(/function kmTxt[\s\S]{0,300}i\.km_unclear/.test(app), 'Werkstattplan zeigt km-Hinweis statt Rest');
  ok(app.includes('(v.km_unclear ? `'), 'Fahrzeugliste kennzeichnet km ungeklärt');
  eq((await owner.post(`${vp}/active`, { active: false, reason: 'Testdaten Plan Tachotausch' })).status, 200);
});

