  eq((await U.driver.post('/api/login', { username: 'w.fahrer', password: 'Sicheres-Passwort-2026' })).status, 200, 'neu anmelden');
  // 2. Kommentar an abgelehnter Meldung: Vorschlags-Werkstatt bekommt nichts
