  eq(st(), 'pending', 'zurückgehalten');
  const b0 = e.pushLog.length; eq((await F.put('/api/me/notify-prefs', { quiet: null })).status, 200);
  eq(st(), 'accepted', 'sofort zugestellt'); eq(e.pushLog.length - b0, 1, 'ein Push');
