  for (const f of ['aktiv', 'aktion', 'alle']) eq((await F.get('/api/contracts?filter=' + f)).data.monthly_rate_sum_net, 800, f);
  // 3. Wiedervorlage-Vermerk bleibt in der App (Befunde/Master-Eingang der Schnittstelle ohne Vermerk)
