    eq((await F.post(`/api/vehicles/${V1}/contracts`, { ...base, partner: 'A', monthly_rate_net: 1000 })).status, 201);
    eq((await F.post(`/api/vehicles/${V2}/contracts`, { ...base, partner: 'B', monthly_rate_net: 500 })).status, 201);
