await test('Winterreifen 19.10.: Auftrag erfüllt abgeschlossen, später wieder Sommerreifen → kein Hinweis „Auftrag abgeschlossen, Lage offen“ mit dem alten Auftrag; ohne Erfüllung bleibt der Hinweis', async () => {
  const { e, U } = await freshWorld(); const F = U.fleet;
  const close = (id, at) => e.DB.prepare(`UPDATE cases SET status='fahrzeug_freigegeben', closed_at=? WHERE id=?`).bind(at, id).run();
  const view = async (V) => { const vh = (await F.get(`/api/vehicles/${V}`)).data.vehicle;
    return { a: (await F.get(`/api/vehicles/${V}/tires`)).data.winter, w: (await F.get('/api/tires/winter')).data.noncompliant.find((x) => x.vehicle_id === vh.id) || null,
      f: (await F.get('/api/tires/fleet')).data.rows.find((x) => x.vehicle_id === vh.id) }; };
  const tire = (V, b) => U.ws.post(`/api/vehicles/${V}/tires/events`, b);
  // A: Winterreifen montiert (erfüllt), Auftrag abgeschlossen, Wochen später Sommerreifen
  eq((await F.post('/api/vehicles', { vin: 'WDB96340310555601', plate: 'DO-WS 1', site: 'Dortmund' })).status, 201); const A = 'VIN:WDB96340310555601';
  const o = await F.post(`/api/vehicles/${A}/tires/winter-order`, { workshop_site: 'DORTMUND', request_key: rk() }); eq(o.status, 201);
  eq((await tire(A, { event_type: 'wechsel', position: 'VA-L', positions: ['VA-R', 'HA-L-aussen', 'HA-R-aussen'], size: '315/70 R22.5', winter_mark: '3pmsf' })).status, 201);
  await close(o.data.id, new Date(Date.now() + 1000).toISOString());
  let r = await view(A); eq(r.a.status, 'erfuellt'); eq(r.a.closed_order, null);
  await new Promise((res) => setTimeout(res, 1100));
  eq((await tire(A, { event_type: 'wechsel', position: 'VA-L', size: '315/70 R22.5', winter_mark: 'keine' })).status, 201);
  r = await view(A); eq(r.a.status, 'nicht_erfuellt'); eq(r.a.closed_order, null, 'Akte: alter erfüllter Auftrag nicht genannt');
  ok(r.w && r.w.closed_order === null, 'Winterliste ohne alten Auftrag'); eq(r.f.winter_closed_order, null, 'Reifen-Flotte ohne alten Auftrag');
  // B: Auftrag abgeschlossen ohne Erfüllung, danach nur Sommerreifen erfasst → Hinweis bleibt (wie bisher)
  eq((await F.post('/api/vehicles', { vin: 'WDB96340310555602', plate: 'DO-WS 2', site: 'Dortmund' })).status, 201); const B = 'VIN:WDB96340310555602';
  const o2 = await F.post(`/api/vehicles/${B}/tires/winter-order`, { workshop_site: 'DORTMUND', request_key: rk() }); eq(o2.status, 201);
  await close(o2.data.id, new Date().toISOString());
  await new Promise((res) => setTimeout(res, 20));
  eq((await tire(B, { event_type: 'wechsel', position: 'VA-L', size: '315/70 R22.5', winter_mark: 'keine' })).status, 201);
  r = await view(B); eq(r.a.status, 'nicht_erfuellt'); eq(r.a.closed_order.case_no, o2.data.case_no, 'nie erfüllt → Hinweis bleibt'); eq(r.f.winter_closed_order.case_no, o2.data.case_no);
});

await test('Fehlersuche 19.10. (51): Bußgeld – Wiederholung meldet „mehrdeutig“, „Fahrer informieren“/„Status setzen“ wiederholbar; falsches altes Passwort meldet nicht ab (400)', async () => {
  const { e, U } = await freshWorld(); const F = U.fleet;
  for (const vin of ['WDB96340310555611', 'WDB96340310555612']) eq((await F.post('/api/vehicles', { vin, plate: 'DO-AM 1', site: 'Dortmund' })).status, 201);
  const body = { kind: 'anhoerung', authority: 'Stadt Dortmund', reference: 'AZ-AMB-1', offense_type: 'geschwindigkeit', offense_at: new Date(Date.now() - 864e5).toISOString(), plate_in_letter: 'DO-AM 1', request_key: 'fine-amb-1' };
  const a = await F.post('/api/fines', body); eq(a.status, 201); eq(a.data.vehicle_ambiguous, true);
  const b = await F.post('/api/fines', { ...body, amount_eur: '35' }); eq(b.data.duplicate, true); eq(b.data.id, a.data.id); eq(b.data.vehicle_ambiguous, true, 'Wiederholung: mehrdeutig');
  // Fahrer bestätigen, informieren – doppelt
  const id = a.data.id; const ver = async () => (await F.get(`/api/fines/${id}`)).data.fine.version;
  eq((await F.post(`/api/fines/${id}/commands`, { action: 'confirm_driver', expected_version: await ver(), payload: { basis: 'manuell', evidence: 'Tourenplan', driver_id: U.driver.id } })).status, 200);
  const v1 = await ver();
  const i1 = await F.post(`/api/fines/${id}/commands`, { action: 'inform_driver', expected_version: v1 }); eq(i1.status, 200);
  const i2 = await F.post(`/api/fines/${id}/commands`, { action: 'inform_driver', expected_version: v1 }); eq(i2.status, 200, 'Wiederholung informieren'); eq(i2.data.duplicate, true);
  const v2 = await ver(); eq(v2, v1 + 1, 'nur eine neue Version');
  const s1 = await F.post(`/api/fines/${id}/commands`, { action: 'set_status', expected_version: v2, payload: { status: 'beantwortet' }, note: 'Anhörungsbogen zurück' }); eq(s1.status, 200);
  const s2 = await F.post(`/api/fines/${id}/commands`, { action: 'set_status', expected_version: v2, payload: { status: 'beantwortet' }, note: 'Anhörungsbogen zurück' }); eq(s2.status, 200, 'Wiederholung Status'); eq(s2.data.duplicate, true);
  eq((await F.post(`/api/fines/${id}/commands`, { action: 'set_status', expected_version: v2, payload: { status: 'eingestellt' }, note: 'x' })).status, 409, 'anderes Ziel auf altem Stand: Konflikt');
  const d = (await F.get(`/api/fines/${id}`)).data; eq(d.events.filter((x) => x.action === 'set_status').length, 1); eq(d.events.filter((x) => x.action === 'inform_driver').length, 1);
  // falsches altes Passwort: 400 (App meldet bei 401 ab)
  const r = await U.viewer.post('/api/me/password', { old_password: 'falsch-falsch-2', new_password: 'Neues-Kennwort-2027y' }); eq(r.status, 400); eq(r.data.error, 'wrong_password');
  eq((await U.viewer.get('/api/me')).status, 200, 'weiter angemeldet');
  void e;
});

await test('Bußgeld 19.10. (Backlog 91): Kennzeichen/Behörde nachträglich korrigierbar – neue Zuordnung, mehrdeutig gemeldet, nur vor Fahrerermittlung, Dublettenprüfung mit neuer Behörde, Verlauf alt → neu', async () => {
  const { U } = await freshWorld(); const F = U.fleet;
  const at = new Date(Date.now() - 864e5).toISOString();
  const a = await F.post('/api/fines', { kind: 'anhoerung', authority: 'Stadt A', reference: 'AZ-91', offense_type: 'geschwindigkeit', offense_at: at, plate_in_letter: 'SZ-YC 5531' }); eq(a.status, 201); eq(a.data.vehicle_matched, false);
  const id = a.data.id; const cur = async () => (await F.get(`/api/fines/${id}`)).data;
  const up = async (payload) => F.post(`/api/fines/${id}/commands`, { action: 'update', expected_version: (await cur()).fine.version, payload });
  let r = await up({ plate_in_letter: 'sz-yc 5513' }); eq(r.status, 200); eq(r.data.vehicle_matched, true);
  let d = await cur(); eq(d.fine.plate_in_letter, 'SZ-YC 5513'); ok(d.fine.vehicle_id, 'zugeordnet'); ok(d.candidates.length >= 0);
  const ev = d.events.filter((x) => x.action === 'update').pop(); const pl = JSON.parse(ev.payload); eq(pl.plate_in_letter, 'SZ-YC 5513');
  // mehrdeutig
  for (const vin of ['WDB96340310555621', 'WDB96340310555622']) eq((await F.post('/api/vehicles', { vin, plate: 'DO-MD 9', site: 'Dortmund' })).status, 201);
  r = await up({ plate_in_letter: 'DO-MD 9' }); eq(r.status, 200); eq(r.data.vehicle_matched, false); eq(r.data.vehicle_ambiguous, true); eq((await cur()).fine.vehicle_id, null);
  eq((await up({ plate_in_letter: '' })).status, 400, 'Kennzeichen Pflicht'); eq((await up({ authority: '' })).status, 400, 'Behörde Pflicht');
  // Dublette über geänderte Behörde
  eq((await F.post('/api/fines', { kind: 'anhoerung', authority: 'Stadt B', reference: 'AZ-91', offense_type: 'geschwindigkeit', offense_at: at, plate_in_letter: 'SZ-YC 5513' })).status, 201);
  r = await up({ authority: 'Stadt B' }); eq(r.status, 409); eq(r.data.error, 'duplicate_fine');
  eq((await up({ authority: 'Stadt C' })).status, 200); eq((await cur()).fine.authority, 'Stadt C');
  // nach Fahrerermittlung: Kennzeichen gesperrt, Behörde weiter änderbar
  eq((await up({ plate_in_letter: 'SZ-YC 5513' })).status, 200);
  eq((await F.post(`/api/fines/${id}/commands`, { action: 'confirm_driver', expected_version: (await cur()).fine.version, payload: { basis: 'manuell', evidence: 'Tourenplan', driver_name_note: 'Fremdfahrer' } })).status, 200);
  r = await up({ plate_in_letter: 'SZ-KC 5515' }); eq(r.status, 409); eq(r.data.error, 'driver_confirmed');
  eq((await up({ plate_in_letter: 'SZ-YC 5513', authority: 'Stadt D' })).status, 200, 'gleiches Kennzeichen + Behörde geht');
  ok([403, 404].includes((await U.ws.post(`/api/fines/${id}/commands`, { action: 'update', payload: { plate_in_letter: 'X' } })).status), 'Werkstatt nicht');
});

await test('Oberfläche 19.10.: Druck ohne Bedienelemente (Foto-/Datei-Knopf, Zurück, Hilfelinks), Druckkopf der Akte unter dem Titel, Reifenpositionen UK/EN im Klartext', async () => {
  const fs = await import('node:fs'); const app = fs.readFileSync(new URL('../public/app.js', import.meta.url), 'utf8'); const css = fs.readFileSync(new URL('../public/styles.css', import.meta.url), 'utf8');
  ok(app.includes('<label class="btn secondary noprint" style="margin-top:8px;display:inline-flex">${esc(t(\'add_photos\'))}'), 'Fotos hinzufügen nicht im Druck');
  ok(app.includes('<label class="btn secondary noprint" style="margin-top:8px;display:inline-flex">${esc(t(\'upload\'))}'), 'Bußgeld-Upload nicht im Druck');
  ok(app.includes('<p class="noprint"><a class="backlink" href="#/fines">') && app.includes('<p class="noprint"><a class="backlink" href="#/drivers">'), 'Zurück-Links nicht im Druck');
  ok(/data-title="\$\{esc\(v\.plate\)\} · \$\{esc\(t\('vehicle_file'\)\)\}"(?: aria-label="[^"]*")?>\$\{esc\(t\('vehicle_file'\)\)\}<\/h1><p class="print-only small">/.test(app), 'Akte: Druckkopf unter dem Titel');
  ok(/h1, h2, h3 \{ break-after: avoid; \}/.test(css) && css.includes('@page guide') && css.includes('page: guide;'), 'Druck-CSS');
  ok(!/(noncompliant|missing)\.join\(', '\)/.test(app), 'Winterpositionen immer über posL');
  // posL wie in der App (ohne Browser): Funktion aus dem Quelltext auswerten
  const { posWord } = await import('../public/finding-messages.js'); ok(app.includes('const posL = (code) => posWord(code, S.lang);'), 'App nutzt gemeinsame Übersetzung');
  const mk = (lang) => (code) => posWord(code, lang);
  eq(mk('de')('HA-L-aussen'), 'HA-L-aussen'); eq(mk('en')('HA-L-aussen'), 'Rear L outer'); eq(mk('en')('AH2-R'), 'Trailer 2 R'); eq(mk('en')('Reserve'), 'Spare wheel');
  eq(mk('uk')('VA-L'), 'Перед. Л'); eq(mk('uk')('XYZ'), 'XYZ', 'Unbekanntes bleibt');
});

await test('Fehlersuche 19.10. (52): Mengen „1,500“ bei englischer Oberfläche mehrdeutig (nicht still 1,5), Deutsch weiter 1,5; alle Feldnamen der Prüfmeldungen übersetzt', async () => {
  const { U } = await freshWorld(); const W = U.ws;
  const it = await W.post('/api/stock', { name: 'Filter EN', initial_qty: '2' }); eq(it.status, 201); const id = it.data.id;
  const onHand = async () => (await W.get(`/api/stock/${id}`)).data.item.on_hand;
  eq((await W.post(`/api/stock/${id}/movements`, { type: 'zugang', qty: '1,500' })).status, 201, 'Deutsch: Dezimalkomma');
  eq(await onHand(), 3.5);
  eq((await W.patch('/api/me', { language: 'en' })).status, 200);
  const r = await W.post(`/api/stock/${id}/movements`, { type: 'zugang', qty: '1,500' }); eq(r.status, 400, 'EN: 1,500 mehrdeutig'); ok(/mehrdeutig/.test(r.data.message), r.data.message);
  eq((await W.post(`/api/stock/${id}/movements`, { type: 'zugang', qty: '1.5' })).status, 201, 'EN: Punkt'); eq(await onHand(), 5);
  eq((await W.post(`/api/vehicles/VIN:WMA15SZZ2HM722774/tires/events`, { event_type: 'messung', position: 'VA-L', tread_mm: '8,500' })).status, 400, 'EN Profiltiefe 8,500 mehrdeutig');
  const { translateValidation } = await import('../public/i18n.js');
  ok(translateValidation('en', 'Menge: „1,500“ ist mehrdeutig – bitte ohne Tausendertrennzeichen (z. B. 15000) bzw. mit Komma für Nachkommastellen (z. B. 2,5) eingeben.').includes('point for decimals'), 'EN-Hinweis nennt Dezimalpunkt');
  // Wächter: jedes Feld aus field:/oneOf(…) hat UK/EN-Namen
  const fs = await import('node:fs');
  const src = fs.readdirSync(new URL('../src/', import.meta.url)).filter((f) => f.endsWith('.js')).map((f) => fs.readFileSync(new URL('../src/' + f, import.meta.url), 'utf8')).join('\n');
  const names = new Set(); for (const m of src.matchAll(/field: '([^'$`]+)'/g)) names.add(m[1]); for (const m of src.matchAll(/oneOf\([^()]*?,\s*[^,()]+,\s*'([^']+)'\)/g)) names.add(m[1]);
  for (const x of ['request_key', 'command_id', 'Version', 'endpoint']) names.delete(x);
  const miss = [...names].filter((n) => /^[a-z]/.test(n) ? false : (translateValidation('en', `${n} ist erforderlich.`) || '').includes(n) && !['Status', 'DOT', 'Position', 'Name'].includes(n)); // gleich geschrieben in EN
  eq(miss.join(', '), '', 'Feldnamen ohne Übersetzung');
});

await test('Integration/Agent 19.10.: since als Datum = Berliner Tagesbeginn, ohne Zone = UTC; Geschwindigkeit > 300 verworfen; gekappte Prüfungslisten halten keine Befunde ruhender/außer Betrieb genommener Fahrzeuge', async () => {
  const { ensureSchema } = await import('../src/worker.js'); const { integrationRouter } = await import('../src/integration.js');
  const e = makeEnv(); await ensureSchema(e); e.INTEGRATION_TOKEN = 'x'.repeat(32); const db = e.DB.db; db.exec('PRAGMA foreign_keys=OFF');
  const get = async (q) => { const url = new URL('https://h/api/integration/v1/cases' + q); return integrationRouter(new Request(url, { headers: { authorization: 'Bearer ' + e.INTEGRATION_TOKEN } }), e, { waitUntil() {} }, url); };
  // Vorgang 00:30 Berliner Zeit am 17.10.2026 (= 16.10. 22:30 UTC)
  db.prepare(`INSERT INTO cases(id,case_no,environment,vehicle_id,reporter_id,description,reported_priority,priority,reported_driveability,status,request_key,content_hash,created_at,updated_at)
    VALUES ('c1','S-2026-9001','production','v1','u1','x','niedrig','niedrig','fahrbereit','gemeldet','rk1','h','2026-10-16T22:30:00.000Z','2026-10-16T22:30:00.000Z')`).run();
  let r = await (await get('?since=2026-10-17')).json(); ok(r.cases.some((c) => c.id === 'c1'), 'Datum: ab 00:00 Berlin');
  r = await (await get('?since=2026-10-16T22:00:00')).json(); ok(r.cases.some((c) => c.id === 'c1'), 'ohne Zone = UTC');
  r = await (await get('?since=2026-10-16T23:00:00')).json(); ok(!r.cases.some((c) => c.id === 'c1'), 'ohne Zone = UTC (danach)');
  { let st = 0; try { st = (await get('?since=2026-02-30')).status; } catch (err) { st = err.status; } eq(st, 400, 'ungültiges Datum'); }
  // Agent: gekappte Liste, Befund eines ruhenden Fahrzeugs wird erledigt
  const ag = (await import('node:fs')).readFileSync(new URL('../src/agent.js', import.meta.url), 'utf8');
  ok(/keepCodes\.has\(ex\.finding_code\) && !\(ex\.vehicle_id && gone\.has\(ex\.vehicle_id\)\)/.test(ag) && ag.includes("SELECT id FROM vehicles WHERE active=0"), 'gekappte Liste: ruhende/außer Betrieb ausgenommen');
  const ig = (await import('node:fs')).readFileSync(new URL('../src/integration.js', import.meta.url), 'utf8'); ok(ig.includes('numOf(it.speed) <= 300'), 'Geschwindigkeit begrenzt');
});

