  const kmSt = async () => ({ ov: (await U.fleet.get('/api/contracts?filter=alle')).data.contracts.find((x) => x.id === c.data.id).status.km, akte: (await U.fleet.get(`/api/vehicles/${V2}`)).data.contracts.find((x) => x.id === c.data.id).status.km });
