await test('Backlog 285 (Blickwinkel „Schaden wird erst Tage später gemeldet“): Schadenzeitpunkt laut Meldung (Migration 0084) – Tag oder Tag + deutsche Uhrzeit, Prüfung, Leitung trägt nach/berichtigt, „N Tage später gemeldet“, Fahrer laut Zuordnung zum Zeitpunkt nur für die Leitung, CSV, Texte DE/UK/EN', async () => {
  const { e, U, V1 } = await freshWorld(); const db = e.DB.db;
  const { berlinLocalToIso, berlinDayStartIso } = await import('../src/util.js');
  const day = (n) => new Date(Date.parse(BERLIN_TODAY + 'T00:00:00Z') + n * 86400000).toISOString().slice(0, 10);
  const send = (extra, key = rk()) => U.driver.post('/api/cases', { vehicle_id: V1, description: 'Delle in der Plane hinten links', priority: 'niedrig', driveability: 'fahrbereit', request_key: key, ...extra });
  // Prüfung
  for (const bad of [day(1), `${day(1)}T00:05`, '2026-02-30', day(-400), 'gestern', '12:30', `${day(-1)}T25:00`]) eq((await send({ occurred_at: bad })).status, 400, `abgewiesen: ${bad}`);
  // Fahrerzuordnungen: Fahrer seit 10 Tagen (offen), andere Person bis vor 5 Tagen
  const vid = (await U.fleet.get('/api/vehicles')).data.vehicles.find((v) => v.plate === 'SZ-YC 5513').id;
  db.prepare(`INSERT INTO driver_vehicles(id,user_id,vehicle_id,valid_from,valid_to,environment,created_by,created_at) VALUES('dv285a',?,?,?,NULL,'test',?,?)`).run(U.driver.id, vid, berlinDayStartIso(day(-10)), U.fleet.id, new Date().toISOString());
  db.prepare(`INSERT INTO driver_vehicles(id,user_id,vehicle_id,valid_from,valid_to,environment,created_by,created_at) VALUES('dv285b',?,?,?,?,'test',?,?)`).run(U.viewer.id, vid, berlinDayStartIso(day(-20)), berlinDayStartIso(day(-5)), U.fleet.id, new Date().toISOString());
  // Tag ohne Uhrzeit
  const key = rk(); const r1 = await send({ occurred_at: day(-3) }, key); eq(r1.status, 201, JSON.stringify(r1.data));
  eq((await send({ occurred_at: day(-3) }, key)).data.duplicate, true, 'erneut gesendet: Dublette');
  eq((await send({ occurred_at: day(-4) }, key)).status, 409, 'gleicher Schlüssel, anderer Zeitpunkt');
  let d = (await U.fleet.get(`/api/cases/${r1.data.id}`)).data;
  eq(d.case.occurred_at, day(-3)); eq(d.occurred_drivers.day_only, true);
  eq(d.occurred_drivers.drivers.map((x) => x.display_name).join(','), 'Fahrer W', 'nur die am Schadentag gültige Zuordnung');
  ok(d.allowed_actions.includes('set_occurred_at'), 'Leitung darf berichtigen');
  const dDrv = (await U.driver.get(`/api/cases/${r1.data.id}`)).data; eq(dDrv.case.occurred_at, day(-3), 'Fahrer sieht eigene Angabe'); ok(!('occurred_drivers' in dDrv) && !dDrv.allowed_actions.includes('set_occurred_at'), 'Fahrer: keine Fahrerliste, kein Berichtigen');
  ok(!('occurred_drivers' in (await U.viewer.get(`/api/cases/${r1.data.id}`)).data), 'Lesezugriff: keine Fahrerliste');
  // Tag + deutsche Uhrzeit → UTC
  const r2 = await send({ occurred_at: `${day(-6)}T14:30` }); eq(r2.status, 201);
  d = (await U.fleet.get(`/api/cases/${r2.data.id}`)).data; eq(d.case.occurred_at, berlinLocalToIso(`${day(-6)}T14:30`));
  eq(d.occurred_drivers.day_only, false); eq(d.occurred_drivers.drivers.map((x) => x.display_name).sort().join(','), 'Fahrer W,Lesen', 'beide Zuordnungen galten');
  // ohne Angabe: leer, keine Fahrerliste; Kontrollmängel nehmen keine Angabe an
  const r3 = await send({}); d = (await U.fleet.get(`/api/cases/${r3.data.id}`)).data; eq(d.case.occurred_at, null); ok(!('occurred_drivers' in d), 'ohne Angabe keine Fahrerliste');
  // Leitung trägt nach / berichtigt / entfernt
  const cmd = async (u, id, occurred_at) => { const c = (await U.fleet.get(`/api/cases/${id}`)).data.case; return u.post(`/api/cases/${id}/commands`, { action: 'set_occurred_at', command_id: rk(), expected_version: c.version, payload: { occurred_at } }); };
  eq((await cmd(U.driver, r3.data.id, day(-1))).status, 403, 'Fahrer nicht');
  eq((await cmd(U.fleet, r3.data.id, `${day(1)}T08:00`)).status, 400, 'nicht nach der Meldung');
  eq((await cmd(U.fleet, r3.data.id, `${day(-2)}T07:15`)).status, 200);
  eq((await cmd(U.fleet, r3.data.id, `${day(-2)}T07:15`)).status, 400, 'unverändert');
  d = (await U.fleet.get(`/api/cases/${r3.data.id}`)).data; eq(d.case.occurred_at, berlinLocalToIso(`${day(-2)}T07:15`));
  const ev = d.events.filter((x) => x.action === 'set_occurred_at').pop(); eq(ev.payload.from, null); eq(ev.payload.to, d.case.occurred_at, 'Verlauf alt → neu');
  eq((await cmd(U.fleet, r3.data.id, '')).status, 200); eq((await U.fleet.get(`/api/cases/${r3.data.id}`)).data.case.occurred_at, null, 'entfernt');
  // CSV
  const csv = new TextDecoder('utf-8', { ignoreBOM: true }).decode((await U.fleet.get('/api/cases?status=all&format=csv')).data);
  ok(csv.split('\r\n')[0].endsWith(';Schadenzeitpunkt laut Meldung'), 'CSV-Kopf');
  const hm = (await import('../src/util.js')).berlinDateTime(berlinLocalToIso(`${day(-6)}T14:30`)); ok(csv.includes(';' + hm + '\r\n') && (csv.includes(';' + day(-3) + '\r\n') || csv.includes(';' + day(-3).split('-').reverse().join('.') + '\r\n')), 'CSV-Werte');
  // Oberfläche und Texte
  const app = (await import('node:fs')).readFileSync(new URL('../public/app.js', import.meta.url), 'utf8');
  ok(app.includes('${occurredFields(null)}') && app.includes("...(occ ? { occurred_at: occ } : {})") && app.includes('data-occurred>') && app.includes("case 'set_occurred_at':"), 'Meldeformular, Anzeige, Formular');
  const { STRINGS, translateValidation } = await import('../public/i18n.js');
  for (const l of ['de', 'uk', 'en']) {
    for (const k of ['occurred', 'act_set_occurred_at', 'occ_date', 'occ_date_hint', 'occ_time', 'occ_time_hint', 'occ_need_date', 'occ_future', 'occ_late', 'occ_drivers', 'occ_drv_assign', 'occ_drv_open', 'occ_drv_check', 'occ_drv_via', 'occ_drv_none', 'occ_drv_hint', 'occ_drv_hint_day', 'occ_drv_more', 'occ_set_hint']) ok(STRINGS[l][k], `${l}.${k}`);
    ok(STRINGS[l].occ_late.includes('{d}'), `${l}.occ_late mit {d}`); ok(STRINGS[l].help_fleet_s.includes(STRINGS[l].act_set_occurred_at), `Hilfe Leitung ${l}`);
  }
  for (const m of ['Schadenzeitpunkt liegt in der Zukunft.', 'Schadenzeitpunkt liegt mehr als ein Jahr zurück.', 'Schadenzeitpunkt: ungültiges Datum.', 'Schadenzeitpunkt ist unverändert.']) ok(translateValidation('en', m) && translateValidation('en', m) !== m, `übersetzt: ${m}`);
});

await test('Backlog 285b: Datenqualität „Offener Versicherungsfall ohne Schadenzeitpunkt“ – verschwindet nach Nachtrag bzw. reguliertem Fall; Texte DE/UK/EN', async () => {
  const { U, cmd, newCase } = await freshWorld();
  const id = await newCase({ description: 'Unfall beim Rangieren, Stoßfänger' });
  eq((await U.fleet.put(`/api/cases/${id}/claim`, { insurer: 'Test-Versicherung', reported_on: BERLIN_TODAY, status: 'gemeldet', evidence: 'Schadenmeldung per Mail' })).status, 200);
  const dq = async () => (await U.fleet.get('/api/admin/data-quality')).data.items.filter((i) => i.check === 'claim_no_occurred');
  let x = await dq(); eq(x.length, 1); eq(x[0].case_id, id); eq(x[0].severity, 'hinweis'); ok(x[0].detail.includes(BERLIN_TODAY), 'Detail mit Meldedatum');
  eq((await cmd(U.fleet, id, 'set_occurred_at', { occurred_at: BERLIN_TODAY })).status, 200);
  eq((await dq()).length, 0, 'nach Nachtrag weg');
  eq((await cmd(U.fleet, id, 'set_occurred_at', { occurred_at: '' })).status, 200); eq((await dq()).length, 1, 'wieder entfernt → Hinweis');
  eq((await U.fleet.put(`/api/cases/${id}/claim`, { insurer: 'Test-Versicherung', reported_on: BERLIN_TODAY, status: 'reguliert', evidence: 'Schadenmeldung per Mail' })).status, 200);
  eq((await dq()).length, 0, 'regulierter Fall: kein Hinweis');
  const { STRINGS } = await import('../public/i18n.js'); for (const l of ['de', 'uk', 'en']) { ok(STRINGS[l].dq_claim_no_occurred, `${l}.dq_claim_no_occurred`); ok(STRINGS[l].claim_no_occ_hint && STRINGS[l].claim_no_occ_hint.includes('{b}'), `${l}.claim_no_occ_hint`); }
  const app = (await import('node:fs')).readFileSync(new URL('../public/app.js', import.meta.url), 'utf8'); ok(app.includes('data-claimnoocc>') && app.includes("['gemeldet', 'in_pruefung'].includes(cl.status)"), 'Hinweis im Versicherungsfall (Backlog 287)');
});

await test('Backlog 288 (Blickwinkel „Leasingrückgabe“): Leasing/Miete endet bald bzw. abgelaufen → offene Vorgänge und offene Restarbeiten freigegebener Vorgänge am Fahrzeug in Übersicht, CSV und Agentenbefund (nur eigene Umgebung); Texte DE/UK/EN', async () => {
  const { e, U, newCase, V1 } = await freshWorld(); const db = e.DB.db;
  const V2 = 'VIN:WDB9630051L917317';
  const day = (n) => new Date(Date.parse(BERLIN_TODAY + 'T00:00:00Z') + n * 86400000).toISOString().slice(0, 10);
  const lea = (await U.fleet.post(`/api/vehicles/${V1}/contracts`, { kind: 'leasing', partner: 'Leasing AG', start_date: day(-700), end_date: day(20), evidence: 'Leasingvertrag' })).data.id;
  const ins = (await U.fleet.post(`/api/vehicles/${V1}/contracts`, { kind: 'versicherung', partner: 'Versicherer', end_date: day(10), evidence: 'Police' })).data.id;
  const mie = (await U.fleet.post(`/api/vehicles/${V2}/contracts`, { kind: 'miete', partner: 'Mietpartner', start_date: day(-60), end_date: day(-2), evidence: 'Mietvertrag' })).data.id;
  const far = (await U.fleet.post(`/api/vehicles/${V2}/contracts`, { kind: 'leasing', partner: 'Später AG', start_date: day(-10), end_date: day(400), evidence: 'Leasingvertrag 2' })).data.id;
  ok(lea && ins && mie && far, 'Verträge angelegt');
  // offener Vorgang + freigegebener Vorgang mit offener Restarbeit (und einer erledigten) an V1
  const c1 = await newCase({ description: 'Kratzer an der Tür' });
  const c2 = await newCase({ description: 'Spiegel lose' });
  const vid = db.prepare('SELECT vehicle_id FROM cases WHERE id=?').get(c2).vehicle_id;
  db.prepare(`UPDATE cases SET status='fahrzeug_freigegeben' WHERE id=?`).run(c2);
  const now = new Date().toISOString();
  db.prepare(`INSERT INTO open_items(id,case_id,description,safety_relevant,status,created_by,created_at) VALUES('oi288a',?,'Lackschaden Tür',0,'offen',?,?)`).run(c2, U.fleet.id, now);
  db.prepare(`INSERT INTO open_items(id,case_id,description,safety_relevant,status,created_by,created_at) VALUES('oi288b',?,'Spiegel justiert',0,'erledigt',?,?)`).run(c2, U.fleet.id, now);
  // Vorgang in der anderen Umgebung zählt nicht
  const cols = db.prepare('PRAGMA table_info(cases)').all().map((x) => x.name);
  const repl = { id: "'c288p'", case_no: "'P-288'", environment: "'production'", status: "'gemeldet'", request_key: "'rk-288p'" };
  db.prepare(`INSERT INTO cases(${cols.join(',')}) SELECT ${cols.map((c) => repl[c] || c).join(',')} FROM cases WHERE id=?`).run(c1);
  ok(c1 && vid, 'Vorgänge');
  let ov = (await U.fleet.get('/api/contracts?filter=alle')).data;
  const by = (id) => ov.contracts.find((c) => c.id === id);
  eq(JSON.stringify(by(lea).return_check), JSON.stringify({ open_cases: 1, open_items: 1 }), 'Leasing endet bald: 1 offener Vorgang, 1 offene Restarbeit');
  eq(JSON.stringify(by(mie).return_check), JSON.stringify({ open_cases: 0, open_items: 0 }), 'Miete abgelaufen, ohne Offenes');
  ok(!by(ins).return_check, 'Versicherung: keine Rückgabe');
  ok(!by(far).return_check, 'Leasing endet nicht bald: nicht geprüft');
  // Stichtag: nicht rekonstruiert → keine Angabe
  ok(!(await U.fleet.get(`/api/contracts?filter=alle&as_of=${day(-1)}`)).data.contracts.some((c) => c.return_check), 'Stichtag ohne Rückgabeprüfung');
  // CSV
  const csv = new TextDecoder('utf-8', { ignoreBOM: true }).decode((await U.fleet.get('/api/contracts?filter=alle&format=csv')).data).split('\r\n');
  ok(csv[0].endsWith(';Offene Vorgänge (Rückgabe);Offene Restarbeiten nach Freigabe (Rückgabe)'), 'CSV-Kopf');
  const row = csv.find((l) => l.includes('Leasing AG')); ok(row && row.endsWith(';1;1'), 'CSV-Werte Leasing');
  ok(csv.find((l) => l.includes('Mietpartner')).endsWith(';0;0'), 'CSV-Werte Miete'); ok(csv.find((l) => l.includes('Versicherer')).endsWith(';;'), 'CSV leer bei Versicherung');
  // Agentenbefund in der Testumgebung nennt die Zahlen, Betrieb nicht
  eq((await U.fleet.post('/api/agent/run')).status, 200);
  const f = (await U.fleet.get('/api/master')).data.findings.find((x) => x.finding_code === 'CONTRACT_ENDS_SOON' && x.message.includes('Leasing AG'));
  ok(f && f.message.includes('offene Vorgänge am Fahrzeug: 1') && f.message.includes('offene Restarbeiten nach Freigabe: 1'), f && f.message);
  const fm2 = (await U.fleet.get('/api/master')).data.findings.find((x) => x.finding_code === 'CONTRACT_ENDED' && x.message.includes('Mietpartner'));
  ok(fm2 && !fm2.message.includes('offene'), 'ohne Offenes kein Zusatz');
  const { contractFindings } = await import('../src/contracts.js');
  const prod = (await contractFindings(e, new Map(), 'production')).find((x) => x.code === 'CONTRACT_ENDS_SOON' && x.message.includes('Leasing AG'));
  ok(prod && prod.message.includes('offene Vorgänge am Fahrzeug: 1') && !prod.message.includes('Restarbeiten'), 'Betrieb: nur der dortige Vorgang');
  // Vorgang abgeschlossen → Zahl sinkt
  db.prepare(`UPDATE cases SET status='abgelehnt' WHERE id=?`).run(c1); db.prepare(`UPDATE open_items SET status='erledigt' WHERE id='oi288a'`).run();
  ov = (await U.fleet.get('/api/contracts?filter=alle')).data; eq(JSON.stringify(by(lea).return_check), JSON.stringify({ open_cases: 0, open_items: 0 }), 'nach Abschluss 0');
  ok((await U.ws.get('/api/contracts')).status === 403, 'Werkstatt sieht keine Verträge');
  // Texte und Oberfläche
  const { STRINGS } = await import('../public/i18n.js'); const { FINDING_MESSAGES } = await import('../public/finding-messages.js');
  for (const l of ['de', 'uk', 'en']) {
    for (const k of ['ct_ret', 'ct_ret_open', 'ct_ret_items', 'ct_ret_clear']) ok(STRINGS[l][k], `${l}.${k}`);
    ok(STRINGS[l].ct_ret_open.includes('{n}') && STRINGS[l].ct_ret_items.includes('{n}'), `${l} Platzhalter`);
    ok(STRINGS[l].help_contracts_s.includes(STRINGS[l].ct_ret), `Hilfe ${l}`);
    for (const k of ['CONTRACT_ENDED', 'CONTRACT_ENDS_SOON']) ok(FINDING_MESSAGES[l][k].includes('{open}') && FINDING_MESSAGES[l][k].includes('{items}'), `${l}.${k}`);
  }
  const app = (await import('node:fs')).readFileSync(new URL('../public/app.js', import.meta.url), 'utf8'); ok(app.includes('${ctRet(c.return_check)}') && app.includes('data-ct-ret'), 'Anzeige in der Vertragsübersicht');
});

await test('Backlog 289: Fahrzeugakte – laufende Leasing-/Mietverträge tragen `return_check` (offene Vorgänge/Restarbeiten, eigene Umgebung), Beenden-Formular zeigt sie mit letztem km-Stand; andere Arten ohne; Texte DE/UK/EN', async () => {
  const { e, U, newCase, V1 } = await freshWorld(); const db = e.DB.db;
  const day = (n) => new Date(Date.parse(BERLIN_TODAY + 'T00:00:00Z') + n * 86400000).toISOString().slice(0, 10);
  const lea = (await U.fleet.post(`/api/vehicles/${V1}/contracts`, { kind: 'leasing', partner: 'Leasing AG', start_date: day(-700), end_date: day(300), evidence: 'Leasingvertrag' })).data.id;
  const ins = (await U.fleet.post(`/api/vehicles/${V1}/contracts`, { kind: 'versicherung', partner: 'Versicherer', end_date: day(100), evidence: 'Police' })).data.id;
  const mie = (await U.fleet.post(`/api/vehicles/${V1}/contracts`, { kind: 'miete', partner: 'Alt-Miete', start_date: day(-900), end_date: day(-720), evidence: 'Mietvertrag' })).data.id;
  eq((await U.fleet.post(`/api/contracts/${mie}/end`, { ended_on: day(-720), end_note: 'zurückgegeben' })).status, 200);
  await newCase({ description: 'Kratzer Tür' }); await newCase({ description: 'Plane eingerissen' });
  let ak = (await U.fleet.get(`/api/vehicles/${V1}`)).data;
  const by = (id) => ak.contracts.find((c) => c.id === id);
  eq(JSON.stringify(by(lea).return_check), JSON.stringify({ open_cases: 2, open_items: 0 }), 'Leasing läuft: auch ohne baldiges Ende geprüft (Beenden jederzeit möglich)');
  ok(!by(ins).return_check && !by(mie).return_check, 'Versicherung und beendete Miete ohne Prüfung');
  eq(by(lea).reading, null, 'ohne km-Stand: nichts geschätzt');
  // Betrieb sieht die Testvorgänge nicht
  const { vehicleContracts } = await import('../src/contracts.js');
  const vid = db.prepare(`SELECT id FROM vehicles WHERE vin='WMA15SZZ2HM722774'`).get().id;
  eq((await vehicleContracts(e, vid, null, new Map(), 'production')).find((c) => c.id === lea).return_check.open_cases, 0, 'andere Umgebung zählt nicht');
  ok(!(await U.ws.get(`/api/vehicles/${V1}`)).data.contracts, 'Werkstatt sieht keine Verträge');
  const { STRINGS } = await import('../public/i18n.js');
  for (const l of ['de', 'uk', 'en']) { for (const k of ['ct_ret_km', 'ct_ret_km_none', 'ct_ret_km_old']) ok(STRINGS[l][k], `${l}.${k}`); ok(STRINGS[l].ct_ret_km.includes('{km}') && STRINGS[l].ct_ret_km.includes('{d}'), `${l} Platzhalter`); ok(STRINGS[l].help_contracts_s.includes(STRINGS[l].ct_ret), `Hilfe ${l}`); }
  const app = (await import('node:fs')).readFileSync(new URL('../public/app.js', import.meta.url), 'utf8'); ok(app.includes('<form data-ctend="${esc(c.id)}">${ctRetEnd(c)}') && app.includes('data-ct-retend'), 'Beenden-Formular');
});

