  for (const x of ['Temperaturanzeige', 'Außentemperaturanzeige zeigt minus', 'Temperaturanzeige vom Kühlaggregat steigt', 'Tankanzeige rot', 'Anzeige rot']) ok(!pat('ENGINE_HINT').test(x), 'kein Motor-Hinweis: ' + x);
